-- New questions for filosofia: 120 questions, each already
-- with its en/es translation (240 translation rows).
--
-- ids are deterministic (uuid5 of the pt-BR prompt), so running this twice
-- inserts nothing new: questions use on conflict do nothing, translations
-- on conflict do update. The translation join refuses any row whose option
-- count differs from the original (correct_index is positional).

insert into questions (id, catalog_node_id, prompt, options, correct_index, explanation, order_index, difficulty)
select v.id::uuid, v.node::uuid, v.prompt, v.options, v.correct_index, v.explanation, v.order_index, v.difficulty
from (values
  ('cdff40db-6aa1-5c31-b9c0-ee72242815ad', '67639d86-d930-5916-aae0-6836ddf062ec',
   'A palavra "filosofia", de origem grega, significa:',
   array['Estudo dos deuses', 'Amor à sabedoria', 'Arte de governar', 'Ciência dos números'], 1,
   '"Filosofia" vem do grego philo (amor, amizade) e sophia (sabedoria): amor ou amizade pela sabedoria.', 100, 'facil'),
  ('f9b303b2-de6c-5885-b196-4ce1bbf13b26', '67639d86-d930-5916-aae0-6836ddf062ec',
   'Segundo Platão e Aristóteles, a filosofia nasce do:',
   array['Medo da morte', 'Desejo de riqueza', 'Respeito às tradições', 'Espanto (admiração) diante do mundo'], 3,
   'Para os dois filósofos, o espanto (thaumazein) diante do que não se compreende é o ponto de partida da investigação filosófica.', 101, 'facil'),
  ('435af806-59da-515f-9fb1-c9f3379a4821', '67639d86-d930-5916-aae0-6836ddf062ec',
   'Uma característica central da atitude filosófica é:',
   array['Questionar o que parece óbvio e buscar justificativas racionais', 'Aceitar as crenças tradicionais sem discussão', 'Basear-se apenas em revelações religiosas', 'Rejeitar qualquer forma de argumentação'], 0,
   'A filosofia problematiza o que é aceito sem exame e exige razões e argumentos para as crenças.', 102, 'medio'),
  ('679c22d9-fba9-5559-bb3b-2a9cbd45143c', '67639d86-d930-5916-aae0-6836ddf062ec',
   'A área da filosofia que investiga o que é o conhecimento e como podemos justificá-lo é a:',
   array['Estética', 'Ética', 'Epistemologia', 'Metafísica'], 2,
   'A epistemologia (teoria do conhecimento) estuda a natureza, as fontes e os limites do conhecimento.', 103, 'medio'),
  ('8d2c0f81-ca31-5053-8cff-e63e1d5b5048', '67639d86-d930-5916-aae0-6836ddf062ec',
   'A distinção entre filosofia e senso comum está melhor expressa em:',
   array['O senso comum é sempre falso, e a filosofia, sempre verdadeira.', 'O senso comum aceita crenças sem examiná-las; a filosofia as submete à crítica racional.', 'A filosofia trata de temas práticos; o senso comum, de temas abstratos.', 'Os dois são idênticos, mudando apenas o vocabulário.'], 1,
   'O senso comum não é necessariamente falso, mas é acrítico; a filosofia examina as crenças e busca seus fundamentos.', 104, 'dificil'),
  ('dbbbd68a-048d-5805-833e-94c69c824c21', '67639d86-d930-5916-aae0-6836ddf062ec',
   'A metafísica, termo associado às obras de Aristóteles, investiga principalmente:',
   array['As regras da boa argumentação', 'Os critérios do belo na arte', 'A organização das cidades', 'O ser enquanto ser e os primeiros princípios da realidade'], 3,
   'A metafísica (ou "filosofia primeira", para Aristóteles) estuda o ser enquanto ser, suas causas e princípios mais gerais.', 105, 'dificil'),
  ('cba2ce8e-dee2-5bbd-a562-dd500b795169', '79054d8c-aca7-5b49-a8ea-3009d4999c4e',
   'Os mitos gregos explicavam a origem do mundo e dos fenômenos principalmente por meio de:',
   array['Experimentos em laboratório', 'Cálculos matemáticos', 'Narrativas envolvendo deuses e heróis', 'Leis escritas pelos governantes'], 2,
   'O mito é uma narrativa sagrada que explica o mundo pela ação de deuses, titãs e heróis.', 106, 'facil'),
  ('52f34930-1699-5e40-8ae3-1ff39bbea052', '79054d8c-aca7-5b49-a8ea-3009d4999c4e',
   'A palavra grega logos, ligada ao nascimento da filosofia, pode ser traduzida como:',
   array['Razão, palavra ou discurso racional', 'Destino imposto pelos deuses', 'Guerra entre cidades', 'Poesia épica'], 0,
   'Logos significa razão, palavra, discurso que explica e dá razões — em contraste com a explicação mítica.', 107, 'facil'),
  ('c6352bc9-cbaa-5d11-a031-01bf369352ad', '79054d8c-aca7-5b49-a8ea-3009d4999c4e',
   'A filosofia surgiu por volta do século VI a.C. nas colônias gregas da Jônia, como Mileto. Um fator que favoreceu esse surgimento foi:',
   array['A proibição total das religiões', 'O contato comercial e cultural com outros povos e a vida na pólis', 'A invenção da imprensa', 'O domínio romano sobre a Grécia'], 1,
   'O comércio, a circulação de ideias, a escrita alfabética e o debate público na pólis criaram condições para o pensamento racional.', 108, 'medio'),
  ('8c6b3c8f-b2e7-5e25-887f-cbf5eec09b82', '79054d8c-aca7-5b49-a8ea-3009d4999c4e',
   'Diferentemente do mito, a explicação filosófica busca:',
   array['Reforçar a autoridade dos sacerdotes', 'Preservar as tradições sem alterá-las', 'Explicar tudo pela vontade dos deuses', 'Princípios naturais que possam ser discutidos e criticados'], 3,
   'A filosofia procura causas e princípios na própria natureza (physis), abertos ao debate e à crítica.', 109, 'medio'),
  ('e86dc2d0-dac5-5504-8fb1-2c852109868e', '79054d8c-aca7-5b49-a8ea-3009d4999c4e',
   'Sobre a passagem do mito ao logos, é correto afirmar que:',
   array['Foi uma ruptura instantânea, sem nenhuma relação entre os dois', 'Eliminou completamente a religião da vida grega', 'Foi um processo gradual, e os primeiros filósofos ainda carregavam elementos do pensamento mítico', 'Aconteceu primeiro em Roma e depois na Grécia'], 2,
   'Muitos estudiosos veem continuidade: a filosofia reorganiza questões do mito (como a origem do cosmo) com outro tipo de explicação.', 110, 'dificil'),
  ('bc2a63e3-713c-5d0d-87cf-de4bdd7e3cc1', '79054d8c-aca7-5b49-a8ea-3009d4999c4e',
   'A busca dos primeiros filósofos pela arché tinha como objetivo encontrar:',
   array['O princípio fundamental de onde tudo se origina', 'O deus mais poderoso do Olimpo', 'A melhor forma de governo', 'As regras da retórica'], 0,
   'Arché é o princípio primeiro, a substância ou origem de todas as coisas — para Tales, por exemplo, a água.', 111, 'dificil'),
  ('1ee1c68e-1d53-5316-b16e-64f4a0d95806', 'd8fbb194-a741-5d29-a914-55b2e2e148f3',
   'Para Tales de Mileto, considerado o primeiro filósofo, o princípio de todas as coisas era:',
   array['O fogo', 'O ar', 'O número', 'A água'], 3,
   'Tales afirmou que a água é a arché, observando que ela está presente em tudo o que vive.', 112, 'facil'),
  ('8800f5c3-40cd-5e68-9b47-72210759335a', 'd8fbb194-a741-5d29-a914-55b2e2e148f3',
   'A frase "ninguém se banha duas vezes no mesmo rio" é atribuída a:',
   array['Parmênides', 'Heráclito', 'Pitágoras', 'Demócrito'], 1,
   'Heráclito defendia que tudo está em constante mudança (devir); o rio e quem se banha nunca são os mesmos.', 113, 'facil'),
  ('def0c166-15f7-5d78-b5ed-08c638659479', 'd8fbb194-a741-5d29-a914-55b2e2e148f3',
   'Contra a ideia de mudança constante, Parmênides afirmou que:',
   array['O ser é, e o não ser não é; a mudança percebida pelos sentidos é ilusão', 'Tudo flui e nada permanece', 'O mundo é formado por quatro elementos', 'Os números são a essência das coisas'], 0,
   'Para Parmênides, o ser é uno, imutável e eterno; a razão, e não os sentidos, alcança a verdade.', 114, 'medio'),
  ('12a7d0b7-be55-5677-8111-f5956d967b06', 'd8fbb194-a741-5d29-a914-55b2e2e148f3',
   'Demócrito e Leucipo defenderam que a realidade é composta por:',
   array['Água, terra, fogo e ar misturados pelo amor e pelo ódio', 'Ideias eternas fora do mundo sensível', 'Partículas indivisíveis (átomos) que se movem no vazio', 'Números e proporções harmônicas'], 2,
   'O atomismo afirma que tudo é formado por átomos, partículas indivisíveis, e pelo vazio em que se movem.', 115, 'medio'),
  ('403cf55a-97be-5768-a603-cce9b56a5ef3', 'd8fbb194-a741-5d29-a914-55b2e2e148f3',
   'Os pré-socráticos também são chamados de "filósofos da natureza" porque:',
   array['Viviam isolados no campo', 'Buscavam explicar a physis (natureza) por princípios racionais', 'Rejeitavam qualquer estudo do cosmo', 'Escreviam apenas sobre agricultura'], 1,
   'Seu tema central era a physis: a origem e a ordem do cosmo, explicadas por princípios naturais.', 116, 'dificil'),
  ('33200932-4632-580b-9edc-b33e176ec8eb', 'd8fbb194-a741-5d29-a914-55b2e2e148f3',
   'Para Pitágoras e seus seguidores, a harmonia do cosmo podia ser compreendida por meio:',
   array['Das quatro raízes: água, terra, fogo e ar', 'Do ápeiron, o ilimitado', 'Da vontade dos deuses olímpicos', 'Dos números e de suas proporções'], 3,
   'Os pitagóricos viam nos números e nas proporções (como nos intervalos musicais) a estrutura da realidade.', 117, 'dificil'),
  ('b888fb1a-647a-5910-a4da-190652959a9c', '3c286a12-1307-5b19-8d56-2f6843ab6ec0',
   'A frase "só sei que nada sei" está associada a:',
   array['Sócrates', 'Aristóteles', 'Tales de Mileto', 'Epicuro'], 0,
   'Sócrates reconhecia a própria ignorância como ponto de partida para buscar o saber verdadeiro.', 118, 'facil'),
  ('98f987f0-9f05-5749-bc8c-07998c083c27', '3c286a12-1307-5b19-8d56-2f6843ab6ec0',
   'O método de Sócrates, baseado em perguntas que levam o interlocutor a reconhecer contradições e "dar à luz" ideias, chama-se:',
   array['Dedução', 'Empirismo', 'Maiêutica', 'Dialética hegeliana'], 2,
   'A maiêutica ("arte do parto") ajuda o interlocutor a descobrir por si mesmo o conhecimento, após a ironia expor suas contradições.', 119, 'facil'),
  ('bc13e5d0-ed07-5357-8cbf-a44fbc3cd323', '3c286a12-1307-5b19-8d56-2f6843ab6ec0',
   'Os sofistas, que ensinavam em Atenas mediante pagamento, eram conhecidos sobretudo por:',
   array['Defender que a verdade só vem da revelação divina', 'Ensinar retórica e a arte de argumentar e persuadir', 'Viver isolados da vida política', 'Estudar exclusivamente a natureza'], 1,
   'Os sofistas ensinavam oratória e argumentação aos cidadãos que queriam participar da vida política da pólis.', 120, 'medio'),
  ('7d224e75-c8fc-57e8-a321-3c625eb8a8a6', '3c286a12-1307-5b19-8d56-2f6843ab6ec0',
   'A frase de Protágoras "o homem é a medida de todas as coisas" expressa uma posição:',
   array['Dogmática, que afirma verdades absolutas', 'Mística, baseada em revelações', 'Materialista, baseada nos átomos', 'Relativista, em que a verdade depende de quem percebe e julga'], 3,
   'Para Protágoras, as coisas são para cada um como lhe aparecem; não haveria uma verdade absoluta independente do ser humano.', 121, 'medio'),
  ('39810917-ea73-5b28-a9d0-bc0ac2a10ca4', '3c286a12-1307-5b19-8d56-2f6843ab6ec0',
   'Sócrates foi condenado à morte em Atenas (399 a.C.) sob a acusação de:',
   array['Corromper a juventude e não reconhecer os deuses da cidade', 'Trair Atenas em favor de Esparta', 'Roubar o tesouro público', 'Escrever livros proibidos'], 0,
   'A acusação era de impiedade e de corromper os jovens; Sócrates aceitou a pena e bebeu a cicuta.', 122, 'dificil'),
  ('ef13c28a-e9d1-5936-b760-a0dae50cd829', '3c286a12-1307-5b19-8d56-2f6843ab6ec0',
   'Uma diferença fundamental entre Sócrates e os sofistas é que Sócrates:',
   array['Cobrava mais caro por suas aulas', 'Defendia que a verdade é relativa a cada pessoa', 'Buscava definições universais (como a do justo) em vez de apenas vencer debates', 'Recusava-se a conversar com os cidadãos'], 2,
   'Sócrates não cobrava e buscava o conceito universal das virtudes; criticava a retórica usada apenas para persuadir.', 123, 'dificil'),
  ('922019e9-836c-589f-9a63-9879723359fb', 'e02ad558-a198-5a7b-8d8e-8b565666f666',
   'Na teoria de Platão, a verdadeira realidade, eterna e imutável, está no:',
   array['Mundo sensível', 'Mundo das Ideias (ou Formas)', 'Mundo dos átomos', 'Mundo dos sonhos'], 1,
   'Para Platão, o mundo sensível é cópia imperfeita e mutável; as Ideias são modelos eternos, alcançados pela razão.', 124, 'facil'),
  ('05a349d5-e01a-5ed4-83c4-cee7533b0a88', 'e02ad558-a198-5a7b-8d8e-8b565666f666',
   'No Mito da Caverna, de Platão, as sombras projetadas na parede representam:',
   array['As Ideias perfeitas', 'O conhecimento filosófico', 'O Sol e o Bem', 'As aparências e opiniões do mundo sensível'], 3,
   'Os prisioneiros tomam as sombras por realidade: assim são as opiniões (doxa) baseadas nos sentidos.', 125, 'facil'),
  ('0f1e3f81-504f-5914-82f5-2695308e179d', 'e02ad558-a198-5a7b-8d8e-8b565666f666',
   'Em A República, Platão defende que a cidade justa deveria ser governada por:',
   array['Filósofos, que conhecem o Bem', 'Guerreiros, os mais fortes', 'Comerciantes, os mais ricos', 'Todos os cidadãos por sorteio'], 0,
   'Para Platão, só quem contempla a Ideia do Bem sabe governar com justiça: o rei-filósofo.', 126, 'medio'),
  ('bf6fbe7e-1946-58e9-95f9-e638c6d307f9', 'e02ad558-a198-5a7b-8d8e-8b565666f666',
   'A teoria da reminiscência, de Platão, afirma que conhecer é:',
   array['Registrar as sensações como numa folha em branco', 'Criar ideias novas a partir do nada', 'Recordar o que a alma já contemplou no mundo das Ideias', 'Aceitar a opinião da maioria'], 2,
   'Para Platão, a alma já contemplou as Ideias antes de encarnar; aprender é relembrar (anamnese).', 127, 'medio'),
  ('91574d34-b188-51bd-a4cd-0b40ef1f9a94', 'e02ad558-a198-5a7b-8d8e-8b565666f666',
   'Na divisão platônica da alma, a parte que deve governar as demais é a:',
   array['Concupiscível (dos desejos)', 'Racional', 'Irascível (da coragem)', 'Vegetativa'], 1,
   'Para Platão, a alma justa é aquela em que a razão governa, a parte irascível a auxilia e os desejos são moderados.', 128, 'dificil'),
  ('08485102-4113-5348-9acb-315779ab68eb', 'e02ad558-a198-5a7b-8d8e-8b565666f666',
   'A obra Apologia de Sócrates, escrita por Platão, apresenta:',
   array['Um tratado sobre a física dos quatro elementos', 'As leis ideais de uma cidade imaginária', 'Um diálogo sobre o amor em um banquete', 'A defesa de Sócrates diante do tribunal que o condenou'], 3,
   'Na Apologia, Platão reconstrói o discurso de defesa de Sócrates no julgamento de 399 a.C.', 129, 'dificil'),
  ('fa9e1d8c-f5c6-5399-9ab9-6f78ea281700', '0add9e0b-d6ef-5a8a-aa14-e1007eb515e6',
   'Aristóteles foi aluno de:',
   array['Sócrates', 'Tales', 'Platão', 'Heráclito'], 2,
   'Aristóteles estudou por cerca de 20 anos na Academia de Platão e depois fundou sua própria escola, o Liceu.', 130, 'facil'),
  ('d3788f75-2ef9-53e1-928e-3ae16f6ff2e6', '0add9e0b-d6ef-5a8a-aa14-e1007eb515e6',
   'Aristóteles definiu o ser humano como um "animal político", o que significa que ele:',
   array['Naturalmente vive em comunidade, na pólis', 'Deve ser governado por reis', 'Nasce sem nenhuma capacidade racional', 'Vive melhor isolado da sociedade'], 0,
   'Para Aristóteles, o humano realiza sua natureza na vida em comunidade, usando a linguagem e a razão.', 131, 'facil'),
  ('8abf746a-6516-5de5-a76c-5076713fe5c7', '0add9e0b-d6ef-5a8a-aa14-e1007eb515e6',
   'Na ética de Aristóteles, a virtude é entendida como:',
   array['O prazer máximo em cada ação', 'A obediência cega às leis divinas', 'A renúncia a todos os desejos', 'A justa medida entre dois extremos (excesso e falta)'], 3,
   'A virtude é o meio-termo: a coragem, por exemplo, fica entre a covardia (falta) e a temeridade (excesso).', 132, 'medio'),
  ('342b8f56-e898-5926-9e50-91716081a50b', '0add9e0b-d6ef-5a8a-aa14-e1007eb515e6',
   'Para Aristóteles, a finalidade última da vida humana é a:',
   array['Riqueza', 'Eudaimonia (felicidade ou vida plena)', 'Fama', 'Contemplação dos deuses olímpicos'], 1,
   'A eudaimonia é o bem supremo, buscado por si mesmo, alcançado pela vida virtuosa segundo a razão.', 133, 'medio'),
  ('8a23dec7-9267-5c9d-85b7-b60004f4b480', '0add9e0b-d6ef-5a8a-aa14-e1007eb515e6',
   'Na teoria das quatro causas de Aristóteles, a causa final de uma estátua é:',
   array['O propósito para o qual ela foi feita', 'O mármore de que é feita', 'O escultor que a produziu', 'A forma que ela tem'], 0,
   'As quatro causas são material (mármore), formal (forma), eficiente (escultor) e final (a finalidade, o "para quê").', 134, 'dificil'),
  ('df033dae-d25e-5173-867f-6067e5e676ff', '0add9e0b-d6ef-5a8a-aa14-e1007eb515e6',
   'Diferentemente de Platão, Aristóteles afirmava que a forma (essência) das coisas:',
   array['Existe apenas num mundo separado das Ideias', 'É uma ilusão dos sentidos', 'Existe nas próprias coisas, unida à matéria', 'Só pode ser conhecida por revelação divina'], 2,
   'Para Aristóteles, forma e matéria são inseparáveis nos seres concretos; não há um mundo das Ideias à parte.', 135, 'dificil'),
  ('49eb67da-1ac9-5181-aba4-478dd63e2d7f', '37a4df58-f99a-5218-b2c0-48a9e6371ddd',
   'Para Epicuro, a felicidade consiste principalmente em:',
   array['Acumular riquezas e poder', 'Alcançar a ataraxia (tranquilidade da alma) e a ausência de dor', 'Obedecer cegamente ao destino', 'Buscar todos os prazeres intensos sem limite'], 1,
   'O prazer epicurista é moderado: ausência de dor no corpo (aponia) e de perturbação na alma (ataraxia).', 136, 'facil'),
  ('21fe0bf4-68f5-5670-80e1-32e13459170d', '37a4df58-f99a-5218-b2c0-48a9e6371ddd',
   'Os estoicos ensinavam que, para viver bem, é preciso:',
   array['Fugir de todas as responsabilidades', 'Buscar a fama a qualquer custo', 'Viver de acordo com a natureza e aceitar o que não depende de nós', 'Duvidar da existência do mundo'], 2,
   'Para o estoicismo, sábio é quem distingue o que está sob seu controle e aceita com serenidade o resto.', 137, 'facil'),
  ('3976ea5c-70bd-55ea-9cfa-49b9dfdfc449', '37a4df58-f99a-5218-b2c0-48a9e6371ddd',
   'Os céticos, como Pirro, recomendavam a suspensão do juízo (epoché) porque:',
   array['Para todo argumento há outro de igual força, e não se pode alcançar certeza', 'A verdade está nos livros sagrados', 'Só os sentidos dão certeza absoluta', 'A razão prova tudo o que existe'], 0,
   'Diante de razões equivalentes, o cético suspende o juízo e busca, com isso, a tranquilidade.', 138, 'medio'),
  ('c7046610-83cf-5a9e-bd58-84c78900a0a6', '37a4df58-f99a-5218-b2c0-48a9e6371ddd',
   'Diógenes de Sínope, que vivia num barril e desprezava convenções sociais, pertencia à escola:',
   array['Estoica', 'Epicurista', 'Cética', 'Cínica'], 3,
   'Os cínicos defendiam uma vida simples, segundo a natureza, rejeitando riquezas e convenções.', 139, 'medio'),
  ('9806c6b7-8b10-5ac3-9474-6e6af73bfc6e', '37a4df58-f99a-5218-b2c0-48a9e6371ddd',
   'As escolas helenísticas surgiram num contexto marcado:',
   array['Pelo auge da democracia ateniense', 'Pelo fim da autonomia das pólis e pela formação de grandes impérios após Alexandre', 'Pela queda do Império Romano do Ocidente', 'Pela Reforma Protestante'], 1,
   'Com as conquistas de Alexandre, a pólis perde autonomia; a filosofia se volta para a busca da tranquilidade individual.', 140, 'dificil'),
  ('47f9d228-ddcb-58cd-80e9-28bf3ef203d6', '37a4df58-f99a-5218-b2c0-48a9e6371ddd',
   'O argumento de Epicuro de que "a morte não é nada para nós" baseia-se na ideia de que:',
   array['A alma é imortal e será julgada pelos deuses', 'A morte é um castigo pelos erros da vida', 'Os deuses controlam o destino humano', 'Quando a morte está presente, nós não estamos, e não há sensação após ela'], 3,
   'Como tudo é sensação e a morte é o fim da sensação, não há por que temê-la.', 141, 'dificil'),
  ('0ff698b4-425e-5e54-9013-c31fda96a780', 'c0001d9e-55ba-5e33-900d-fe980f5e511e',
   'Um tema central da filosofia medieval foi a relação entre:',
   array['Fé e razão', 'Átomos e vazio', 'Capital e trabalho', 'Mito e logos'], 0,
   'Pensadores medievais buscaram conciliar a fé cristã com a razão filosófica herdada dos gregos.', 142, 'facil'),
  ('a03e60b9-ee8b-50f0-a7e6-ab1d86ad16ca', 'c0001d9e-55ba-5e33-900d-fe980f5e511e',
   'Santo Agostinho, principal nome da Patrística, foi fortemente influenciado pela filosofia de:',
   array['Aristóteles', 'Epicuro', 'Platão', 'Demócrito'], 2,
   'Agostinho aproximou o cristianismo do pensamento platônico (via neoplatonismo).', 143, 'facil'),
  ('19321bc2-f00d-53e0-8303-b850d9f15a71', 'c0001d9e-55ba-5e33-900d-fe980f5e511e',
   'São Tomás de Aquino, principal nome da Escolástica, buscou conciliar a fé cristã com a filosofia de:',
   array['Platão', 'Aristóteles', 'Heráclito', 'Pitágoras'], 1,
   'Tomás de Aquino integrou o pensamento aristotélico à teologia cristã, por exemplo nas Cinco Vias.', 144, 'medio'),
  ('3c5f648c-4161-5a8a-80f1-4e741049ffa2', 'c0001d9e-55ba-5e33-900d-fe980f5e511e',
   'Para Santo Agostinho, o mal:',
   array['É uma substância criada por Deus', 'É uma força igual e oposta a Deus', 'Não existe de forma alguma no mundo', 'É ausência (privação) do bem, ligada ao mau uso do livre-arbítrio'], 3,
   'Agostinho define o mal como privação do bem; o mal moral nasce do mau uso da liberdade humana.', 145, 'medio'),
  ('c2269299-758b-5a05-945e-d1cce0f92f02', 'c0001d9e-55ba-5e33-900d-fe980f5e511e',
   'As "Cinco Vias" de Tomás de Aquino são:',
   array['Argumentos racionais para demonstrar a existência de Deus', 'Regras para a vida monástica', 'Etapas do método científico moderno', 'Críticas à Igreja Católica'], 0,
   'Nas Cinco Vias (primeiro motor, causa primeira, ser necessário etc.), Tomás argumenta racionalmente pela existência de Deus.', 146, 'dificil'),
  ('21e8419b-b0c7-55de-92fe-605f22563cda', 'c0001d9e-55ba-5e33-900d-fe980f5e511e',
   'A chamada "querela dos universais" discutia:',
   array['Se a Terra está no centro do universo', 'Quem deveria ser o papa', 'Se conceitos gerais (como "humanidade") existem de fato ou são apenas nomes', 'Se a Bíblia deveria ser traduzida'], 2,
   'Realistas afirmavam que os universais existem; nominalistas, como Guilherme de Ockham, que são apenas nomes.', 147, 'dificil'),
  ('d2f13a7c-7f28-5f16-b122-9e1f3506a6d6', 'f8bb74a3-4f0f-5018-95ba-24d901e2d0e1',
   'A frase "Penso, logo existo" é de:',
   array['John Locke', 'René Descartes', 'David Hume', 'Immanuel Kant'], 1,
   'Descartes chega ao cogito: mesmo duvidando de tudo, a existência de quem pensa é indubitável.', 148, 'facil'),
  ('ca0d0075-c6f1-5ca4-abe2-db4fb502c98e', 'f8bb74a3-4f0f-5018-95ba-24d901e2d0e1',
   'Para os racionalistas, a principal fonte do conhecimento seguro é:',
   array['A tradição', 'A experiência sensível', 'A revelação religiosa', 'A razão'], 3,
   'O racionalismo (Descartes, Spinoza, Leibniz) considera a razão a fonte do conhecimento certo e universal.', 149, 'facil'),
  ('891b4094-a9f6-5800-b78a-07ae783ecef8', 'f8bb74a3-4f0f-5018-95ba-24d901e2d0e1',
   'A dúvida metódica de Descartes consiste em:',
   array['Duvidar de tudo para sempre, sem chegar a nenhuma certeza', 'Aceitar apenas o que os sentidos mostram', 'Duvidar de tudo o que possa ser posto em dúvida, para encontrar uma verdade indubitável', 'Confiar nas opiniões dos antigos'], 2,
   'A dúvida cartesiana é um método, não um fim: serve para chegar a uma primeira certeza segura (o cogito).', 150, 'medio'),
  ('50e29685-f593-5b63-a003-498bc4048cf2', 'f8bb74a3-4f0f-5018-95ba-24d901e2d0e1',
   'Descartes dividiu a realidade em duas substâncias, a pensante e a extensa. Essa posição é chamada de:',
   array['Dualismo', 'Materialismo', 'Monismo', 'Ceticismo'], 0,
   'O dualismo cartesiano separa res cogitans (mente, pensamento) e res extensa (corpo, matéria).', 151, 'medio'),
  ('d321e282-1a63-5460-911d-e58959577219', 'f8bb74a3-4f0f-5018-95ba-24d901e2d0e1',
   'Para Descartes, as ideias inatas são aquelas que:',
   array['Vêm dos sentidos após o nascimento', 'São inventadas pela imaginação', 'São ensinadas pela sociedade', 'Já estão na mente, como a ideia de Deus e as verdades matemáticas'], 3,
   'Descartes distingue ideias adventícias (dos sentidos), fictícias (imaginação) e inatas (presentes na razão).', 152, 'dificil'),
  ('ceb041b6-0e93-5958-94c9-0ce505e08d11', 'f8bb74a3-4f0f-5018-95ba-24d901e2d0e1',
   'Spinoza, racionalista do século XVII, identificou Deus com:',
   array['Um ser pessoal separado do mundo', 'A própria natureza (Deus sive Natura)', 'O primeiro motor imóvel de Aristóteles', 'A vontade do soberano'], 1,
   'Para Spinoza há uma única substância, Deus ou Natureza; tudo o que existe é modo dessa substância.', 153, 'dificil'),
  ('f6f7ea15-eaba-5a52-92ec-b7ca0eb5bde9', 'e04660bb-584e-558f-b0ec-45c0c6d1fdd9',
   'Para os empiristas, todo conhecimento tem origem na:',
   array['Razão pura', 'Revelação divina', 'Experiência sensível', 'Intuição mística'], 2,
   'O empirismo (Locke, Berkeley, Hume) afirma que o conhecimento vem da experiência.', 154, 'facil'),
  ('bba4eb7e-9131-5bda-aba5-fb9aeee2c452', 'e04660bb-584e-558f-b0ec-45c0c6d1fdd9',
   'John Locke comparou a mente humana, ao nascer, a:',
   array['Uma folha em branco (tábula rasa)', 'Uma biblioteca completa', 'Um espelho perfeito', 'Uma máquina de calcular'], 0,
   'Para Locke não há ideias inatas: a mente começa vazia e é preenchida pela experiência.', 155, 'facil'),
  ('4a1e4ac3-9f8b-5bb2-8764-57a35abf64bd', 'e04660bb-584e-558f-b0ec-45c0c6d1fdd9',
   'David Hume criticou a ideia de causalidade afirmando que ela se baseia:',
   array['Em demonstrações matemáticas', 'Em ideias inatas', 'Na revelação divina', 'No hábito de ver eventos se sucederem, e não numa conexão necessária percebida'], 3,
   'Vemos que um fato segue outro repetidamente e, por hábito, esperamos que continue; a necessidade não é observada.', 156, 'medio'),
  ('2380222e-eafc-528e-adcf-9b00fa4c0660', 'e04660bb-584e-558f-b0ec-45c0c6d1fdd9',
   'A frase "ser é ser percebido" (esse est percipi) resume a filosofia de:',
   array['John Locke', 'George Berkeley', 'Francis Bacon', 'Thomas Hobbes'], 1,
   'Para Berkeley, as coisas só existem enquanto percebidas (por nós ou por Deus).', 157, 'medio'),
  ('a1344253-c467-5d4d-ac01-e367d953aec8', 'e04660bb-584e-558f-b0ec-45c0c6d1fdd9',
   'Francis Bacon chamou de "ídolos" os:',
   array['Deuses das religiões antigas', 'Governantes que abusam do poder', 'Preconceitos e erros da mente que atrapalham o conhecimento verdadeiro', 'Métodos matemáticos de investigação'], 2,
   'Bacon descreve ídolos da tribo, da caverna, do foro (mercado) e do teatro, que distorcem o conhecimento.', 158, 'dificil'),
  ('d83a2894-5ca1-5a02-a9b9-76961466883d', 'e04660bb-584e-558f-b0ec-45c0c6d1fdd9',
   'O chamado "problema da indução", formulado por Hume, questiona:',
   array['Como justificar conclusões gerais a partir de casos particulares observados', 'Como provar teoremas geométricos', 'Por que os governos devem existir', 'Como distinguir o belo do feio'], 0,
   'Observar muitos casos não garante logicamente que o próximo será igual; a indução não tem justificativa racional plena.', 159, 'dificil'),
  ('23da65ac-8809-52bd-b541-3e7ecc800787', '0b283daf-de23-528e-ae67-779667037a10',
   'Para Kant, o Esclarecimento (Iluminismo) é a saída do ser humano da:',
   array['Vida no campo', 'Menoridade, ou seja, da incapacidade de usar o próprio entendimento sem a direção de outro', 'Religião cristã', 'Monarquia absolutista'], 1,
   'No texto "O que é o Esclarecimento?", Kant convida: "Ousa saber! Tem coragem de usar teu próprio entendimento".', 160, 'facil'),
  ('1b2e50f2-0192-5979-a95d-565120da63a9', '0b283daf-de23-528e-ae67-779667037a10',
   'O imperativo categórico de Kant manda agir:',
   array['Buscando sempre o maior prazer', 'Conforme o que a maioria aprova', 'De acordo com as leis do Estado, sem exceção', 'Apenas segundo uma máxima que você possa querer que se torne lei universal'], 3,
   'A ação é moral quando sua máxima pode ser universalizada, feita por dever, e não por interesse.', 161, 'facil'),
  ('a2d4f29a-8724-5835-a753-e1444eca4e49', '0b283daf-de23-528e-ae67-779667037a10',
   'Kant é conhecido por propor uma síntese entre:',
   array['Racionalismo e empirismo', 'Epicurismo e estoicismo', 'Platonismo e atomismo', 'Cristianismo e islamismo'], 0,
   'Para Kant, o conhecimento começa com a experiência, mas nem tudo nele vem dela: a razão contribui com formas e categorias.', 162, 'medio'),
  ('88623ea5-5c0b-55f5-9e43-f9996a11f818', '0b283daf-de23-528e-ae67-779667037a10',
   'A chamada "revolução copernicana" de Kant na teoria do conhecimento afirma que:',
   array['A Terra gira em torno do Sol', 'O conhecimento depende apenas dos objetos', 'Os objetos se regulam pelas estruturas do sujeito que conhece', 'Só Deus pode conhecer a realidade'], 2,
   'Em vez de o sujeito se adaptar ao objeto, é o objeto conhecido que se adapta às formas da sensibilidade e às categorias do entendimento.', 163, 'medio'),
  ('bc920f54-9919-5eda-ae0b-05438803d533', '0b283daf-de23-528e-ae67-779667037a10',
   'Kant distingue o fenômeno do númeno. O númeno (coisa em si) é:',
   array['Aquilo que aparece aos nossos sentidos', 'A realidade tal como é em si mesma, que não podemos conhecer', 'Uma ideia inata de Descartes', 'Um conceito matemático'], 1,
   'Só conhecemos os fenômenos (as coisas como nos aparecem); a coisa em si pode ser pensada, mas não conhecida.', 164, 'dificil'),
  ('6380ed68-8753-569b-9882-ce3e95551f2f', '0b283daf-de23-528e-ae67-779667037a10',
   'Uma das formulações do imperativo categórico diz que devemos tratar a humanidade:',
   array['Como meio para alcançar a felicidade geral', 'Conforme a utilidade de cada pessoa', 'Segundo a vontade do governante', 'Sempre como fim, e nunca apenas como meio'], 3,
   'A fórmula da humanidade exige respeitar a dignidade das pessoas: ninguém pode ser usado apenas como instrumento.', 165, 'dificil'),
  ('102723c8-5c65-53c2-8a31-ec89d636ff94', '9f5fa8f4-6414-5204-851f-5c3eedb44a74',
   'A ética, como área da filosofia, se dedica principalmente a:',
   array['Estudar os astros e o universo', 'Classificar as espécies de seres vivos', 'Refletir sobre valores, o bem e como devemos agir', 'Descrever a formação das línguas'], 2,
   'A ética investiga os fundamentos do agir humano: o que é bom, justo e como devemos viver.', 166, 'facil'),
  ('d6a38d6b-b689-5117-a2e5-d9c753ffe8c0', '9f5fa8f4-6414-5204-851f-5c3eedb44a74',
   'Uma distinção comum entre moral e ética é que:',
   array['A moral são as normas e costumes de um grupo; a ética é a reflexão crítica sobre essas normas', 'A moral trata da natureza; a ética, da política', 'Moral e ética são termos sem nenhuma relação', 'A ética só existe nas religiões'], 0,
   'A moral (mores, costumes) é o conjunto de regras vividas; a ética as examina e busca seus fundamentos.', 167, 'facil'),
  ('7cc71b4b-aef7-5cc1-8d79-bad285150493', '9f5fa8f4-6414-5204-851f-5c3eedb44a74',
   'Para que uma ação possa ser avaliada moralmente, é pressuposto que o agente tenha:',
   array['Riqueza suficiente', 'Apoio da maioria', 'Conhecimento científico avançado', 'Consciência e liberdade para escolher'], 3,
   'Só se atribui responsabilidade moral a quem age com consciência e liberdade; ações forçadas ou ignorantes atenuam a culpa.', 168, 'medio'),
  ('e882e904-27aa-5bad-9aab-c93cdfc73f50', '9f5fa8f4-6414-5204-851f-5c3eedb44a74',
   'O relativismo moral defende que:',
   array['Existe uma única moral válida para todos os povos', 'Os valores morais variam conforme a cultura e a época', 'Só a ciência define o que é certo', 'As leis naturais determinam todos os costumes'], 1,
   'Para o relativismo, não há padrão moral universal: o certo e o errado dependem do contexto cultural.', 169, 'medio'),
  ('0c5d21f4-b31c-512b-846d-19a6ec8b5d2f', '9f5fa8f4-6414-5204-851f-5c3eedb44a74',
   'Em debates de bioética, como sobre eutanásia ou clonagem, a filosofia contribui principalmente ao:',
   array['Fornecer respostas prontas e indiscutíveis', 'Substituir a legislação vigente', 'Analisar argumentos e princípios envolvidos, como autonomia e dignidade', 'Proibir qualquer avanço científico'], 2,
   'A bioética examina os dilemas trazidos pela ciência à luz de princípios como autonomia, beneficência e justiça.', 170, 'dificil'),
  ('8d399448-3acd-538d-8687-ff57682ec60a', '9f5fa8f4-6414-5204-851f-5c3eedb44a74',
   'O chamado "dilema do bonde", em que se decide desviar um veículo para salvar cinco pessoas sacrificando uma, é usado para discutir:',
   array['O conflito entre calcular consequências e respeitar deveres ou direitos individuais', 'As leis da física do movimento', 'A história dos transportes públicos', 'A origem mítica do mundo'], 0,
   'O dilema contrapõe o raciocínio consequencialista (salvar mais vidas) a princípios que proíbem usar alguém como meio.', 171, 'dificil'),
  ('5be1ac01-86fd-5673-874d-b79171e84376', '98e54340-cdfb-599b-9763-701186b0bf62',
   'O utilitarismo, de Jeremy Bentham e John Stuart Mill, avalia uma ação como correta quando ela:',
   array['Obedece à tradição religiosa', 'Produz a maior felicidade para o maior número de pessoas', 'É feita apenas por dever', 'Beneficia somente quem a pratica'], 1,
   'O utilitarismo é consequencialista: julga as ações pelos resultados em termos de bem-estar geral.', 172, 'facil'),
  ('c885b972-ab34-5453-bbf6-68431f11a33f', '98e54340-cdfb-599b-9763-701186b0bf62',
   'A ética de Kant é chamada de ética do dever (deontológica) porque:',
   array['Avalia as ações apenas pelos resultados', 'Busca o prazer como fim último', 'Segue a vontade da maioria', 'O valor moral da ação está em ser feita por dever, segundo a razão'], 3,
   'Para Kant, a ação moral é a feita por respeito à lei moral, independentemente das consequências.', 173, 'facil'),
  ('2ec2f8cb-eb43-5a49-ae34-d9af2476b2fe', '98e54340-cdfb-599b-9763-701186b0bf62',
   'A ética das virtudes, de origem aristotélica, pergunta principalmente:',
   array['Que tipo de pessoa devo ser e que hábitos devo cultivar?', 'Qual ação gera mais prazer?', 'Quais regras universais devo seguir sem exceção?', 'O que a lei do Estado permite?'], 0,
   'A ética das virtudes foca o caráter: tornar-se justo, corajoso e prudente por meio da prática.', 174, 'medio'),
  ('71640ef7-2ae5-5d0a-86ac-ce893be07ff9', '98e54340-cdfb-599b-9763-701186b0bf62',
   'John Stuart Mill aperfeiçoou o utilitarismo de Bentham ao afirmar que:',
   array['Todos os prazeres têm exatamente o mesmo valor', 'Só o dever importa, não as consequências', 'Há prazeres superiores (intelectuais) e inferiores, que diferem em qualidade', 'A felicidade não tem importância moral'], 2,
   'Mill diz que é melhor ser um humano insatisfeito do que um porco satisfeito: a qualidade dos prazeres conta.', 175, 'medio'),
  ('c26fc5dd-3fef-574e-bd36-657e76b57e37', '98e54340-cdfb-599b-9763-701186b0bf62',
   'Uma crítica frequente ao utilitarismo é que ele pode:',
   array['Ignorar completamente o bem-estar das pessoas', 'Justificar sacrificar os direitos de uma minoria em nome do bem-estar da maioria', 'Exigir que se siga a tradição religiosa', 'Proibir qualquer cálculo de consequências'], 1,
   'Se só importa o saldo de felicidade, ações injustas contra poucos poderiam ser aprovadas; daí a defesa de direitos individuais.', 176, 'dificil'),
  ('57d1b7a7-707d-5381-ace2-9cbff8b7e029', '98e54340-cdfb-599b-9763-701186b0bf62',
   'Segundo Kant, mentir para salvar um amigo de um assassino seria:',
   array['Correto, pois a consequência é boa', 'Correto, se a maioria concordar', 'Indiferente do ponto de vista moral', 'Errado, pois a proibição de mentir não admite exceções baseadas nas consequências'], 3,
   'Na polêmica com Benjamin Constant, Kant sustenta que o dever de veracidade vale incondicionalmente.', 177, 'dificil'),
  ('22fe91d7-908f-5f51-90f1-59772785860e', 'b7daaf58-ae78-5323-b4de-9734deba702f',
   'A obra mais conhecida de Nicolau Maquiavel, que trata de como conquistar e manter o poder, é:',
   array['O Príncipe', 'A República', 'Leviatã', 'O Contrato Social'], 0,
   'Em O Príncipe (1513), Maquiavel analisa a política como ela é, e não como deveria ser.', 178, 'facil'),
  ('6f37139c-0c65-5bf8-b6cb-d96da282358e', 'b7daaf58-ae78-5323-b4de-9734deba702f',
   'Para Maquiavel, o governante precisa ter virtù, que significa:',
   array['Pureza religiosa', 'Riqueza herdada', 'Capacidade de agir com habilidade diante das circunstâncias', 'Obediência ao papa'], 2,
   'Virtù é a capacidade do príncipe de aproveitar a ocasião e enfrentar a fortuna (o acaso).', 179, 'facil'),
  ('b8ab2e8e-662c-563b-b93e-24eb8ef1eecd', 'b7daaf58-ae78-5323-b4de-9734deba702f',
   'Maquiavel é considerado um fundador da ciência política moderna porque:',
   array['Defendeu que a política deve seguir a moral cristã', 'Separou a análise política da moral e da religião, observando a realidade', 'Criou o sistema de três poderes', 'Propôs o fim de todos os governos'], 1,
   'Ele descreve o funcionamento real do poder, com autonomia em relação à moral tradicional.', 180, 'medio'),
  ('e82c24e5-14bb-516b-93d4-0318cfa085ab', 'b7daaf58-ae78-5323-b4de-9734deba702f',
   'Sobre a pergunta "é melhor ser amado ou temido?", Maquiavel responde que o príncipe:',
   array['Deve ser apenas amado', 'Deve ser odiado para impor respeito', 'Não precisa se preocupar com isso', 'Seria ideal ser ambos, mas, se tiver de escolher, é mais seguro ser temido, sem ser odiado'], 3,
   'O amor depende da vontade dos súditos; o temor, do príncipe. Mas ele deve evitar o ódio.', 181, 'medio'),
  ('17b3b10f-b001-5b58-8cc0-535c85cba28f', 'b7daaf58-ae78-5323-b4de-9734deba702f',
   'Os conceitos de virtù e fortuna, em Maquiavel, indicam que:',
   array['Tudo na política depende do destino, e nada pode ser feito', 'Os governantes são escolhidos por Deus', 'O sucesso político depende da capacidade do governante de enfrentar o acaso', 'A história é regida apenas por leis econômicas'], 2,
   'A fortuna governa parte das coisas, mas a virtù pode resistir e dominar as circunstâncias.', 182, 'dificil'),
  ('9a1c479c-d447-5073-8201-20e479b75189', 'b7daaf58-ae78-5323-b4de-9734deba702f',
   'A expressão "os fins justificam os meios", atribuída popularmente a Maquiavel, é considerada uma simplificação porque:',
   array['Ele analisa as ações pelo objetivo de manter o Estado, e não autoriza qualquer ação para qualquer fim', 'Ele nunca tratou de política', 'Ele defendia que a moral cristã deve sempre prevalecer', 'Ele era contra qualquer governo forte'], 0,
   'A frase não aparece literalmente na obra; Maquiavel avalia as ações do príncipe pela preservação do Estado.', 183, 'dificil'),
  ('0e884ebc-a856-5511-9f00-deb253875cf4', '140f3cc9-4b63-51f6-8116-fc2d90926190',
   'Para Thomas Hobbes, no estado de natureza, sem governo, a vida humana seria:',
   array['Pacífica e harmoniosa', 'Uma guerra de todos contra todos', 'Organizada pela Igreja', 'Regida pela propriedade privada'], 1,
   'Hobbes descreve a vida sem Estado como "solitária, pobre, sórdida, brutal e curta": o homem é o lobo do homem.', 184, 'facil'),
  ('4e032cfc-14a4-5262-a61b-fe778b8b784c', '140f3cc9-4b63-51f6-8116-fc2d90926190',
   'A frase "o homem nasce bom, a sociedade o corrompe" é associada a:',
   array['Thomas Hobbes', 'John Locke', 'Nicolau Maquiavel', 'Jean-Jacques Rousseau'], 3,
   'Rousseau via o ser humano naturalmente bom; a propriedade e a desigualdade social o corrompem.', 185, 'facil'),
  ('71891489-fa57-533f-be2e-941bc104f544', '140f3cc9-4b63-51f6-8116-fc2d90926190',
   'Para John Locke, os direitos naturais que o governo deve proteger são:',
   array['Vida, liberdade e propriedade', 'Obediência, fé e trabalho', 'Poder, glória e riqueza', 'Igualdade absoluta de bens'], 0,
   'Locke fundamenta o liberalismo: o Estado existe para proteger esses direitos, e o povo pode resistir ao governo tirânico.', 186, 'medio'),
  ('f26c749a-bf3d-5bda-a87e-932101140e88', '140f3cc9-4b63-51f6-8116-fc2d90926190',
   'Em Rousseau, a "vontade geral" é:',
   array['A soma dos interesses particulares de cada um', 'A vontade do rei absoluto', 'A vontade orientada ao bem comum, que expressa a soberania do povo', 'A opinião dos mais ricos'], 2,
   'A vontade geral visa o interesse comum e é a base da soberania popular, que não pode ser alienada.', 187, 'medio'),
  ('7f8ce014-2db2-5060-bab0-82de54395b19', '140f3cc9-4b63-51f6-8116-fc2d90926190',
   'Em Leviatã, Hobbes justifica um poder soberano forte porque:',
   array['O rei é escolhido diretamente por Deus', 'A propriedade é um direito absoluto anterior ao Estado', 'O povo deve participar diretamente de todas as decisões', 'Só um poder capaz de impor medo garante a paz e a segurança que os indivíduos buscam ao fazer o contrato'], 3,
   'Os indivíduos transferem seus direitos ao soberano em troca de segurança; sem ele, voltariam à guerra de todos contra todos.', 188, 'dificil'),
  ('3cbebab8-ab74-5ad6-96bf-7246aadf13a8', '140f3cc9-4b63-51f6-8116-fc2d90926190',
   'O que Hobbes, Locke e Rousseau têm em comum é a ideia de que:',
   array['O poder dos reis tem origem divina', 'A legitimidade do Estado se funda num acordo (contrato) entre os indivíduos', 'O estado de natureza é idêntico para os três', 'A propriedade deve ser abolida'], 1,
   'Os três são contratualistas, embora divirjam sobre o estado de natureza e o tipo de governo legítimo.', 189, 'dificil'),
  ('414112ff-3211-5a99-ba61-d6c7e437ee1a', 'dd3a9919-5d53-5c89-a0a0-e96d66435b09',
   'A frase "Deus está morto" é associada a:',
   array['Friedrich Nietzsche', 'Karl Marx', 'René Descartes', 'Santo Agostinho'], 0,
   'Nietzsche usa a expressão para indicar o esgotamento dos valores tradicionais da cultura ocidental.', 190, 'facil'),
  ('89b610a8-a506-5012-8999-f01c90512bf2', 'dd3a9919-5d53-5c89-a0a0-e96d66435b09',
   'Nietzsche propôs a "transvaloração de todos os valores", que significa:',
   array['Aceitar sem críticas a moral tradicional', 'Transformar todos os valores em dinheiro', 'Criticar os valores tradicionais e criar novos, afirmativos da vida', 'Voltar aos valores da Idade Média'], 2,
   'Nietzsche critica a moral que nega a vida e propõe valores que afirmem a vontade e a existência.', 191, 'facil'),
  ('80f3cd23-f668-5b39-ae03-e6fd2f684ae1', 'dd3a9919-5d53-5c89-a0a0-e96d66435b09',
   'Em Nietzsche, a "moral de escravos" é aquela que:',
   array['Nasce da força e da afirmação da vida', 'Nasce do ressentimento dos fracos, que invertem os valores dos fortes', 'Foi criada pelos antigos gregos heroicos', 'Valoriza o orgulho e a nobreza'], 1,
   'Na Genealogia da Moral, a moral de escravos transforma fraqueza em virtude e condena o que é forte.', 192, 'medio'),
  ('c65b167d-7e6c-577d-ac2f-9f2144d51f1f', 'dd3a9919-5d53-5c89-a0a0-e96d66435b09',
   'O conceito nietzschiano de super-homem (Übermensch) refere-se a alguém que:',
   array['Tem poderes sobrenaturais', 'Obedece rigorosamente às leis religiosas', 'Busca a igualdade absoluta entre todos', 'Supera os valores herdados e cria os próprios valores'], 3,
   'O Übermensch é uma meta: o ser humano que se supera e afirma a vida criando valores próprios.', 193, 'medio'),
  ('b81ff383-8f2f-566e-8215-30bfcb4cedb2', 'dd3a9919-5d53-5c89-a0a0-e96d66435b09',
   'Em O Nascimento da Tragédia, Nietzsche contrapõe dois impulsos da cultura grega:',
   array['O racional e o empírico', 'O político e o religioso', 'O apolíneo (forma, medida) e o dionisíaco (embriaguez, excesso)', 'O material e o espiritual'], 2,
   'A tragédia grega nasceria da união entre o apolíneo, da ordem e da forma, e o dionisíaco, da força vital e do caos.', 194, 'dificil'),
  ('336986fe-0150-5c54-a6dc-c750576a6dbe', 'dd3a9919-5d53-5c89-a0a0-e96d66435b09',
   'A ideia do eterno retorno, em Nietzsche, funciona como um teste que pergunta:',
   array['Você desejaria viver sua vida exatamente igual, infinitas vezes?', 'Qual é o princípio de todas as coisas?', 'Como provar a existência de Deus?', 'Qual é a melhor forma de governo?'], 0,
   'Quem consegue querer o eterno retorno de sua vida a afirma plenamente, sem ressentimento.', 195, 'dificil'),
  ('60bbe3b3-b865-50c4-8cd5-bbe25de697d8', 'a07e6784-aeb7-594e-81e8-53b90dbe31f1',
   'Para Jean-Paul Sartre, "a existência precede a essência", o que significa que:',
   array['Nascemos com uma natureza fixa definida por Deus', 'O ser humano primeiro existe e depois se define por suas escolhas', 'A essência humana é determinada pela biologia', 'Nada do que fazemos importa'], 1,
   'Não há natureza humana prévia: somos o que fazemos de nós mesmos.', 196, 'facil'),
  ('a451d51d-52d2-54da-b625-6e72ff0495c4', 'a07e6784-aeb7-594e-81e8-53b90dbe31f1',
   'A frase "o homem está condenado a ser livre" é de:',
   array['Nietzsche', 'Kant', 'Marx', 'Sartre'], 3,
   'Para Sartre, não podemos escapar da liberdade: mesmo não escolher é uma escolha.', 197, 'facil'),
  ('1e9345bb-73c8-5e5e-afd2-3032581d33df', 'a07e6784-aeb7-594e-81e8-53b90dbe31f1',
   'A frase "não se nasce mulher, torna-se mulher", de Simone de Beauvoir, afirma que:',
   array['Ser mulher é uma construção social e histórica, e não um destino biológico', 'As mulheres devem se afastar da vida pública', 'A natureza define todos os papéis sociais', 'Homens e mulheres não têm nenhuma diferença biológica'], 0,
   'Em O Segundo Sexo, Beauvoir mostra como os papéis femininos são construídos pela sociedade.', 198, 'medio'),
  ('0537f264-f8dc-515a-bdf4-b81afa32d64c', 'a07e6784-aeb7-594e-81e8-53b90dbe31f1',
   'Para Sartre, a "má-fé" ocorre quando a pessoa:',
   array['Mente para os outros por interesse', 'Pratica uma religião', 'Nega a própria liberdade, fingindo que não tinha escolha', 'Duvida de tudo metodicamente'], 2,
   'Na má-fé, a pessoa se esconde da angústia da liberdade atribuindo suas ações ao destino, à natureza ou aos outros.', 199, 'medio'),
  ('037980cd-437a-5b3e-9500-aa53cdef4f11', 'a07e6784-aeb7-594e-81e8-53b90dbe31f1',
   'Para Albert Camus, em O Mito de Sísifo, o absurdo surge:',
   array['Da certeza de que a vida tem um sentido dado por Deus', 'Do confronto entre a busca humana por sentido e o silêncio do mundo', 'Da vitória da razão sobre as emoções', 'Da organização política da sociedade'], 1,
   'Camus conclui que "é preciso imaginar Sísifo feliz": a revolta lúcida diante do absurdo dá valor à vida.', 200, 'dificil'),
  ('c601a511-b8f4-5ba5-af47-0cde8b5cb299', 'a07e6784-aeb7-594e-81e8-53b90dbe31f1',
   'Para os existencialistas, a angústia é:',
   array['Uma doença que deve ser curada com remédios', 'Um sentimento exclusivo de quem não tem religião', 'Resultado da falta de riqueza', 'A experiência de perceber-se livre e responsável pelas próprias escolhas, sem garantias'], 3,
   'A angústia revela a liberdade: ao escolher, respondemos por nós e, de certo modo, pela humanidade.', 201, 'dificil'),
  ('1ae5ffaf-aaf8-5f01-917a-da3d2cc36c73', '96f3b16c-0a11-57ea-972f-15e84363cc58',
   'A Escola de Frankfurt ficou conhecida por desenvolver a:',
   array['Lógica formal', 'Filosofia escolástica', 'Teoria crítica da sociedade', 'Física quântica'], 2,
   'A teoria crítica, de autores como Adorno, Horkheimer, Marcuse e Habermas, analisa criticamente a sociedade moderna.', 202, 'facil'),
  ('d11c5e79-838b-5f1b-947d-fe2dfe9b480f', '96f3b16c-0a11-57ea-972f-15e84363cc58',
   'Adorno e Horkheimer criaram o conceito de "indústria cultural" para criticar:',
   array['A produção em massa de cultura como mercadoria padronizada', 'As artes tradicionais dos povos indígenas', 'A educação pública gratuita', 'A agricultura industrial'], 0,
   'A indústria cultural transforma cultura em produto de consumo padronizado, que favorece o conformismo.', 203, 'facil'),
  ('cd837e04-4c5f-56ef-b899-fd06e88ee2e2', '96f3b16c-0a11-57ea-972f-15e84363cc58',
   'A "razão instrumental", criticada pela Escola de Frankfurt, é a razão que:',
   array['Reflete sobre os fins últimos da vida humana', 'Busca apenas a verdade desinteressada', 'Se opõe a qualquer técnica', 'Se preocupa apenas com os meios mais eficientes, sem questionar os fins'], 3,
   'Na Dialética do Esclarecimento, a razão reduzida a cálculo e eficiência pode servir à dominação.', 204, 'medio'),
  ('131154a6-c5c5-50bf-8643-76ea185969be', '96f3b16c-0a11-57ea-972f-15e84363cc58',
   'Jürgen Habermas propôs a ação comunicativa, baseada:',
   array['Na força e na coerção', 'No diálogo racional em busca de entendimento entre os participantes', 'Na obediência a líderes carismáticos', 'No cálculo individual de vantagens'], 1,
   'Para Habermas, normas legítimas surgem do debate livre em que valem os melhores argumentos.', 205, 'medio'),
  ('7c36a691-3acd-5f3b-965c-ef00c5c13e9c', '96f3b16c-0a11-57ea-972f-15e84363cc58',
   'Walter Benjamin, em "A obra de arte na era de sua reprodutibilidade técnica", afirma que a reprodução em massa:',
   array['Aumenta a aura única da obra original', 'Impede qualquer acesso do público à arte', 'Faz a obra perder sua "aura", mas amplia o acesso e muda sua função social', 'Não altera em nada a relação com a arte'], 2,
   'A fotografia e o cinema retiram a unicidade (aura) da obra, mas democratizam o acesso e politizam a arte.', 206, 'dificil'),
  ('0f931db6-d9bf-5b0b-97c8-8ab956cd0994', '96f3b16c-0a11-57ea-972f-15e84363cc58',
   'Herbert Marcuse, em O Homem Unidimensional, critica a sociedade industrial avançada porque ela:',
   array['Integra os indivíduos ao consumo e reduz sua capacidade de pensar alternativas críticas', 'Impede totalmente o consumo', 'Retorna ao modo de vida feudal', 'Elimina toda forma de tecnologia'], 0,
   'A abundância e o consumo criariam falsas necessidades que neutralizam a crítica e a oposição.', 207, 'dificil'),
  ('6940e7c6-c453-58a4-a3b6-93013cfc90e9', '6eb0a23e-9547-58bc-b796-bc9b105e2b92',
   'Um argumento é formado por:',
   array['Apenas uma opinião pessoal', 'Premissas e uma conclusão que se apoia nelas', 'Perguntas sem resposta', 'Uma lista de definições'], 1,
   'No argumento, as premissas oferecem razões para aceitar a conclusão.', 208, 'facil'),
  ('98b61246-e156-5557-9095-28e377f26d0d', '6eb0a23e-9547-58bc-b796-bc9b105e2b92',
   '"Todo homem é mortal. Sócrates é homem. Logo, Sócrates é mortal." Esse argumento é um exemplo de:',
   array['Indução', 'Falácia', 'Analogia', 'Silogismo dedutivo'], 3,
   'No silogismo de Aristóteles, a conclusão decorre necessariamente das duas premissas.', 209, 'facil'),
  ('d057f4b5-5621-5df6-90ca-cb34ed028aa7', '6eb0a23e-9547-58bc-b796-bc9b105e2b92',
   'Atacar a pessoa que apresenta um argumento, em vez de discutir o argumento em si, é a falácia chamada:',
   array['Ad hominem', 'Apelo à autoridade', 'Falsa causa', 'Espantalho'], 0,
   'Na falácia ad hominem, desqualifica-se o autor para rejeitar sua ideia, sem examiná-la.', 210, 'medio'),
  ('20102b0c-85ec-5632-8cb7-2c313201393a', '6eb0a23e-9547-58bc-b796-bc9b105e2b92',
   'Um argumento indutivo se caracteriza por:',
   array['Ter conclusão necessariamente verdadeira se as premissas forem verdadeiras', 'Não ter premissas', 'Partir de casos particulares para uma conclusão geral provável', 'Ser sempre uma falácia'], 2,
   'A indução generaliza a partir de observações; sua conclusão é provável, não necessária.', 211, 'medio'),
  ('8e2b6a16-1232-5800-8215-a204384b64ce', '6eb0a23e-9547-58bc-b796-bc9b105e2b92',
   'Em lógica, um argumento é válido quando:',
   array['Todas as suas premissas são verdadeiras', 'É impossível as premissas serem verdadeiras e a conclusão falsa', 'A maioria das pessoas concorda com ele', 'A conclusão é verdadeira, qualquer que seja o raciocínio'], 1,
   'Validade diz respeito à forma: se as premissas forem verdadeiras, a conclusão necessariamente será. Um argumento válido pode ter premissas falsas.', 212, 'dificil'),
  ('dfe37131-95bd-530c-a503-5eb24928a087', '6eb0a23e-9547-58bc-b796-bc9b105e2b92',
   'Distorcer a posição do oponente, tornando-a mais fraca, para depois refutá-la facilmente é a falácia do:',
   array['Apelo à emoção', 'Ad hominem', 'Falso dilema', 'Espantalho'], 3,
   'Na falácia do espantalho, refuta-se uma versão caricata do argumento, e não o argumento real.', 213, 'dificil'),
  ('be3c35be-f27d-5579-82a1-234041569d81', '03fd0820-41a9-5f12-ae35-299579f84f9a',
   'A definição clássica de conhecimento, discutida desde Platão, é:',
   array['Qualquer opinião que alguém tenha', 'Aquilo que a maioria acredita', 'Crença verdadeira e justificada', 'Tudo o que está escrito nos livros'], 2,
   'Para haver conhecimento, não basta crer: a crença precisa ser verdadeira e bem justificada.', 214, 'facil'),
  ('5a07fd65-1073-5ef7-bfc8-184f84ec53d8', '03fd0820-41a9-5f12-ae35-299579f84f9a',
   'O ceticismo, na teoria do conhecimento, é a posição que:',
   array['Duvida da possibilidade de alcançarmos conhecimento certo', 'Afirma que tudo pode ser conhecido com certeza', 'Defende que só a religião dá conhecimento', 'Considera a experiência sensível infalível'], 0,
   'O cético questiona se é possível ter certeza; alguns suspendem o juízo, outros duvidam de áreas específicas.', 215, 'facil'),
  ('00a79b7b-c19f-5b76-ac7f-c0d6e58fc776', '03fd0820-41a9-5f12-ae35-299579f84f9a',
   'Para Karl Popper, uma teoria é científica quando:',
   array['Pode ser provada verdadeira definitivamente', 'É aceita pela maioria dos cientistas', 'Foi formulada por um cientista famoso', 'Pode ser falseada, isto é, testada e potencialmente refutada pela experiência'], 3,
   'O critério da falseabilidade distingue ciência de não ciência: teorias científicas correm o risco de ser refutadas.', 216, 'medio'),
  ('c995fd0b-2309-59b9-a78d-5202bb302faf', '03fd0820-41a9-5f12-ae35-299579f84f9a',
   'Thomas Kuhn chamou de "revolução científica" o momento em que:',
   array['A ciência para de progredir', 'Um paradigma é substituído por outro, como na passagem do geocentrismo ao heliocentrismo', 'Os cientistas se recusam a fazer experiências', 'A religião passa a controlar a ciência'], 1,
   'Para Kuhn, a ciência normal opera dentro de um paradigma; anomalias acumuladas levam a uma troca de paradigma.', 217, 'medio'),
  ('5f9fa0ec-365f-584e-a165-57f1c405b0a0', '03fd0820-41a9-5f12-ae35-299579f84f9a',
   'O chamado "problema de Gettier" mostrou que a definição de conhecimento como crença verdadeira justificada:',
   array['Pode falhar, pois há casos de crença verdadeira e justificada que parecem não ser conhecimento', 'É perfeita e não admite críticas', 'Foi criada por Descartes', 'Só vale para a matemática'], 0,
   'Gettier apresentou casos em que alguém acerta por sorte, com boa justificativa, sem de fato saber.', 218, 'dificil'),
  ('6ef6217a-0c0e-5688-b204-9863a1660e1c', '03fd0820-41a9-5f12-ae35-299579f84f9a',
   'A distinção de Kant entre juízos analíticos e sintéticos afirma que um juízo analítico:',
   array['Amplia nosso conhecimento com dados da experiência', 'Depende sempre da observação empírica', 'Tem o predicado contido no conceito do sujeito, como em "todo solteiro é não casado"', 'É sempre falso'], 2,
   'No juízo analítico, o predicado apenas explicita o sujeito; o sintético acrescenta algo novo ao conceito.', 219, 'dificil')
) as v(id, node, prompt, options, correct_index, explanation, order_index, difficulty)
join catalog_nodes c on c.id = v.node::uuid
on conflict (id) do nothing;

insert into question_translations (question_id, locale, prompt, options, explanation)
select v.id::uuid, v.locale, v.prompt, v.options, v.explanation
from (values
  ('cdff40db-6aa1-5c31-b9c0-ee72242815ad', 'en',
   'The word "philosophy", of Greek origin, means:',
   array['Study of the gods', 'Love of wisdom', 'Art of governing', 'Science of numbers'],
   '"Philosophy" comes from the Greek philo (love, friendship) and sophia (wisdom): love or friendship of wisdom.'),
  ('cdff40db-6aa1-5c31-b9c0-ee72242815ad', 'es',
   'La palabra "filosofía", de origen griego, significa:',
   array['Estudio de los dioses', 'Amor a la sabiduría', 'Arte de gobernar', 'Ciencia de los números'],
   '"Filosofía" viene del griego philo (amor, amistad) y sophia (sabiduría): amor o amistad por la sabiduría.'),
  ('f9b303b2-de6c-5885-b196-4ce1bbf13b26', 'en',
   'According to Plato and Aristotle, philosophy is born from:',
   array['Fear of death', 'Desire for wealth', 'Respect for tradition', 'Wonder at the world'],
   'For both philosophers, wonder (thaumazein) at what is not understood is the starting point of philosophical inquiry.'),
  ('f9b303b2-de6c-5885-b196-4ce1bbf13b26', 'es',
   'Según Platón y Aristóteles, la filosofía nace del:',
   array['Miedo a la muerte', 'Deseo de riqueza', 'Respeto a las tradiciones', 'Asombro ante el mundo'],
   'Para ambos filósofos, el asombro (thaumazein) ante lo que no se comprende es el punto de partida de la investigación filosófica.'),
  ('435af806-59da-515f-9fb1-c9f3379a4821', 'en',
   'A central feature of the philosophical attitude is:',
   array['Questioning what seems obvious and seeking rational justification', 'Accepting traditional beliefs without discussion', 'Relying only on religious revelation', 'Rejecting any form of argument'],
   'Philosophy questions what is accepted without examination and demands reasons and arguments for beliefs.'),
  ('435af806-59da-515f-9fb1-c9f3379a4821', 'es',
   'Una característica central de la actitud filosófica es:',
   array['Cuestionar lo que parece obvio y buscar justificaciones racionales', 'Aceptar las creencias tradicionales sin discusión', 'Basarse solo en revelaciones religiosas', 'Rechazar cualquier forma de argumentación'],
   'La filosofía problematiza lo que se acepta sin examen y exige razones y argumentos para las creencias.'),
  ('679c22d9-fba9-5559-bb3b-2a9cbd45143c', 'en',
   'The area of philosophy that investigates what knowledge is and how we can justify it is:',
   array['Aesthetics', 'Ethics', 'Epistemology', 'Metaphysics'],
   'Epistemology (theory of knowledge) studies the nature, sources and limits of knowledge.'),
  ('679c22d9-fba9-5559-bb3b-2a9cbd45143c', 'es',
   'El área de la filosofía que investiga qué es el conocimiento y cómo podemos justificarlo es la:',
   array['Estética', 'Ética', 'Epistemología', 'Metafísica'],
   'La epistemología (teoría del conocimiento) estudia la naturaleza, las fuentes y los límites del conocimiento.'),
  ('8d2c0f81-ca31-5053-8cff-e63e1d5b5048', 'en',
   'The difference between philosophy and common sense is best expressed in:',
   array['Common sense is always false, and philosophy always true.', 'Common sense accepts beliefs without examining them; philosophy subjects them to rational criticism.', 'Philosophy deals with practical matters; common sense with abstract ones.', 'They are identical, only the vocabulary changes.'],
   'Common sense is not necessarily false, but it is uncritical; philosophy examines beliefs and seeks their grounds.'),
  ('8d2c0f81-ca31-5053-8cff-e63e1d5b5048', 'es',
   'La diferencia entre filosofía y sentido común está mejor expresada en:',
   array['El sentido común siempre es falso, y la filosofía, siempre verdadera.', 'El sentido común acepta creencias sin examinarlas; la filosofía las somete a la crítica racional.', 'La filosofía trata temas prácticos; el sentido común, temas abstractos.', 'Ambos son idénticos, solo cambia el vocabulario.'],
   'El sentido común no es necesariamente falso, pero es acrítico; la filosofía examina las creencias y busca sus fundamentos.'),
  ('dbbbd68a-048d-5805-833e-94c69c824c21', 'en',
   'Metaphysics, a term associated with Aristotle''s works, mainly investigates:',
   array['The rules of good reasoning', 'The criteria of beauty in art', 'The organization of cities', 'Being as being and the first principles of reality'],
   'Metaphysics ("first philosophy" for Aristotle) studies being as being, its causes and most general principles.'),
  ('dbbbd68a-048d-5805-833e-94c69c824c21', 'es',
   'La metafísica, término asociado a las obras de Aristóteles, investiga principalmente:',
   array['Las reglas de la buena argumentación', 'Los criterios de lo bello en el arte', 'La organización de las ciudades', 'El ser en cuanto ser y los primeros principios de la realidad'],
   'La metafísica ("filosofía primera" para Aristóteles) estudia el ser en cuanto ser, sus causas y principios más generales.'),
  ('cba2ce8e-dee2-5bbd-a562-dd500b795169', 'en',
   'Greek myths explained the origin of the world and of natural events mainly through:',
   array['Laboratory experiments', 'Mathematical calculations', 'Stories involving gods and heroes', 'Laws written by rulers'],
   'Myth is a sacred narrative that explains the world through the actions of gods, titans and heroes.'),
  ('cba2ce8e-dee2-5bbd-a562-dd500b795169', 'es',
   'Los mitos griegos explicaban el origen del mundo y de los fenómenos principalmente mediante:',
   array['Experimentos de laboratorio', 'Cálculos matemáticos', 'Narraciones con dioses y héroes', 'Leyes escritas por los gobernantes'],
   'El mito es una narración sagrada que explica el mundo por la acción de dioses, titanes y héroes.'),
  ('52f34930-1699-5e40-8ae3-1ff39bbea052', 'en',
   'The Greek word logos, linked to the birth of philosophy, can be translated as:',
   array['Reason, word or rational discourse', 'Fate imposed by the gods', 'War between cities', 'Epic poetry'],
   'Logos means reason, word, discourse that explains and gives reasons — in contrast to mythical explanation.'),
  ('52f34930-1699-5e40-8ae3-1ff39bbea052', 'es',
   'La palabra griega logos, ligada al nacimiento de la filosofía, puede traducirse como:',
   array['Razón, palabra o discurso racional', 'Destino impuesto por los dioses', 'Guerra entre ciudades', 'Poesía épica'],
   'Logos significa razón, palabra, discurso que explica y da razones, en contraste con la explicación mítica.'),
  ('c6352bc9-cbaa-5d11-a031-01bf369352ad', 'en',
   'Philosophy emerged around the 6th century BC in the Greek colonies of Ionia, such as Miletus. A factor that favored this was:',
   array['The total ban on religions', 'Trade and cultural contact with other peoples and life in the polis', 'The invention of the printing press', 'Roman rule over Greece'],
   'Trade, the circulation of ideas, alphabetic writing and public debate in the polis created conditions for rational thought.'),
  ('c6352bc9-cbaa-5d11-a031-01bf369352ad', 'es',
   'La filosofía surgió hacia el siglo VI a. C. en las colonias griegas de Jonia, como Mileto. Un factor que favoreció ese surgimiento fue:',
   array['La prohibición total de las religiones', 'El contacto comercial y cultural con otros pueblos y la vida en la polis', 'La invención de la imprenta', 'El dominio romano sobre Grecia'],
   'El comercio, la circulación de ideas, la escritura alfabética y el debate público en la polis crearon condiciones para el pensamiento racional.'),
  ('8c6b3c8f-b2e7-5e25-887f-cbf5eec09b82', 'en',
   'Unlike myth, the philosophical explanation seeks:',
   array['To reinforce the authority of priests', 'To preserve traditions without changing them', 'To explain everything by the will of the gods', 'Natural principles that can be discussed and criticized'],
   'Philosophy looks for causes and principles in nature itself (physis), open to debate and criticism.'),
  ('8c6b3c8f-b2e7-5e25-887f-cbf5eec09b82', 'es',
   'A diferencia del mito, la explicación filosófica busca:',
   array['Reforzar la autoridad de los sacerdotes', 'Preservar las tradiciones sin cambiarlas', 'Explicarlo todo por la voluntad de los dioses', 'Principios naturales que puedan discutirse y criticarse'],
   'La filosofía busca causas y principios en la propia naturaleza (physis), abiertos al debate y a la crítica.'),
  ('e86dc2d0-dac5-5504-8fb1-2c852109868e', 'en',
   'About the shift from myth to logos, it is correct to say that:',
   array['It was an instant break, with no relation between the two', 'It completely eliminated religion from Greek life', 'It was a gradual process, and the first philosophers still carried elements of mythical thought', 'It happened first in Rome and then in Greece'],
   'Many scholars see continuity: philosophy reorganizes questions from myth (such as the origin of the cosmos) with another kind of explanation.'),
  ('e86dc2d0-dac5-5504-8fb1-2c852109868e', 'es',
   'Sobre el paso del mito al logos, es correcto afirmar que:',
   array['Fue una ruptura instantánea, sin ninguna relación entre ambos', 'Eliminó por completo la religión de la vida griega', 'Fue un proceso gradual, y los primeros filósofos aún llevaban elementos del pensamiento mítico', 'Ocurrió primero en Roma y luego en Grecia'],
   'Muchos estudiosos ven continuidad: la filosofía reorganiza preguntas del mito (como el origen del cosmos) con otro tipo de explicación.'),
  ('bc2a63e3-713c-5d0d-87cf-de4bdd7e3cc1', 'en',
   'The first philosophers'' search for the arché aimed to find:',
   array['The fundamental principle from which everything originates', 'The most powerful god of Olympus', 'The best form of government', 'The rules of rhetoric'],
   'Arché is the first principle, the substance or origin of all things — for Thales, for example, water.'),
  ('bc2a63e3-713c-5d0d-87cf-de4bdd7e3cc1', 'es',
   'La búsqueda de los primeros filósofos por el arjé tenía como objetivo encontrar:',
   array['El principio fundamental del que todo se origina', 'El dios más poderoso del Olimpo', 'La mejor forma de gobierno', 'Las reglas de la retórica'],
   'El arjé es el principio primero, la sustancia u origen de todas las cosas; para Tales, por ejemplo, el agua.'),
  ('1ee1c68e-1d53-5316-b16e-64f4a0d95806', 'en',
   'For Thales of Miletus, considered the first philosopher, the principle of all things was:',
   array['Fire', 'Air', 'Number', 'Water'],
   'Thales stated that water is the arché, noting that it is present in everything that lives.'),
  ('1ee1c68e-1d53-5316-b16e-64f4a0d95806', 'es',
   'Para Tales de Mileto, considerado el primer filósofo, el principio de todas las cosas era:',
   array['El fuego', 'El aire', 'El número', 'El agua'],
   'Tales afirmó que el agua es el arjé, observando que está presente en todo lo que vive.'),
  ('8800f5c3-40cd-5e68-9b47-72210759335a', 'en',
   'The saying "no one steps in the same river twice" is attributed to:',
   array['Parmenides', 'Heraclitus', 'Pythagoras', 'Democritus'],
   'Heraclitus held that everything is in constant change (becoming); neither the river nor the bather is ever the same.'),
  ('8800f5c3-40cd-5e68-9b47-72210759335a', 'es',
   'La frase "nadie se baña dos veces en el mismo río" se atribuye a:',
   array['Parménides', 'Heráclito', 'Pitágoras', 'Demócrito'],
   'Heráclito sostenía que todo está en cambio constante (devenir); ni el río ni quien se baña son nunca los mismos.'),
  ('def0c166-15f7-5d78-b5ed-08c638659479', 'en',
   'Against the idea of constant change, Parmenides stated that:',
   array['Being is, and non-being is not; the change perceived by the senses is illusion', 'Everything flows and nothing remains', 'The world is made of four elements', 'Numbers are the essence of things'],
   'For Parmenides, being is one, unchanging and eternal; reason, not the senses, reaches the truth.'),
  ('def0c166-15f7-5d78-b5ed-08c638659479', 'es',
   'Contra la idea de cambio constante, Parménides afirmó que:',
   array['El ser es y el no ser no es; el cambio percibido por los sentidos es ilusión', 'Todo fluye y nada permanece', 'El mundo está formado por cuatro elementos', 'Los números son la esencia de las cosas'],
   'Para Parménides, el ser es uno, inmutable y eterno; la razón, y no los sentidos, alcanza la verdad.'),
  ('12a7d0b7-be55-5677-8111-f5956d967b06', 'en',
   'Democritus and Leucippus argued that reality is composed of:',
   array['Water, earth, fire and air mixed by love and strife', 'Eternal ideas outside the sensible world', 'Indivisible particles (atoms) moving in the void', 'Numbers and harmonic proportions'],
   'Atomism states that everything is made of atoms, indivisible particles, and the void in which they move.'),
  ('12a7d0b7-be55-5677-8111-f5956d967b06', 'es',
   'Demócrito y Leucipo defendieron que la realidad está compuesta por:',
   array['Agua, tierra, fuego y aire mezclados por el amor y el odio', 'Ideas eternas fuera del mundo sensible', 'Partículas indivisibles (átomos) que se mueven en el vacío', 'Números y proporciones armónicas'],
   'El atomismo afirma que todo está formado por átomos, partículas indivisibles, y por el vacío en que se mueven.'),
  ('403cf55a-97be-5768-a603-cce9b56a5ef3', 'en',
   'The Pre-Socratics are also called "philosophers of nature" because:',
   array['They lived isolated in the countryside', 'They sought to explain physis (nature) through rational principles', 'They rejected any study of the cosmos', 'They wrote only about agriculture'],
   'Their central theme was physis: the origin and order of the cosmos, explained by natural principles.'),
  ('403cf55a-97be-5768-a603-cce9b56a5ef3', 'es',
   'A los presocráticos también se les llama "filósofos de la naturaleza" porque:',
   array['Vivían aislados en el campo', 'Buscaban explicar la physis (naturaleza) por principios racionales', 'Rechazaban cualquier estudio del cosmos', 'Escribían solo sobre agricultura'],
   'Su tema central era la physis: el origen y el orden del cosmos, explicados por principios naturales.'),
  ('33200932-4632-580b-9edc-b33e176ec8eb', 'en',
   'For Pythagoras and his followers, the harmony of the cosmos could be understood through:',
   array['The four roots: water, earth, fire and air', 'The apeiron, the boundless', 'The will of the Olympian gods', 'Numbers and their proportions'],
   'The Pythagoreans saw in numbers and proportions (as in musical intervals) the structure of reality.'),
  ('33200932-4632-580b-9edc-b33e176ec8eb', 'es',
   'Para Pitágoras y sus seguidores, la armonía del cosmos podía comprenderse mediante:',
   array['Las cuatro raíces: agua, tierra, fuego y aire', 'El ápeiron, lo ilimitado', 'La voluntad de los dioses olímpicos', 'Los números y sus proporciones'],
   'Los pitagóricos veían en los números y las proporciones (como en los intervalos musicales) la estructura de la realidad.'),
  ('b888fb1a-647a-5910-a4da-190652959a9c', 'en',
   'The phrase "I know that I know nothing" is associated with:',
   array['Socrates', 'Aristotle', 'Thales of Miletus', 'Epicurus'],
   'Socrates acknowledged his own ignorance as the starting point for seeking true knowledge.'),
  ('b888fb1a-647a-5910-a4da-190652959a9c', 'es',
   'La frase "solo sé que no sé nada" está asociada a:',
   array['Sócrates', 'Aristóteles', 'Tales de Mileto', 'Epicuro'],
   'Sócrates reconocía su propia ignorancia como punto de partida para buscar el saber verdadero.'),
  ('98f987f0-9f05-5749-bc8c-07998c083c27', 'en',
   'Socrates'' method, based on questions that lead the other person to see contradictions and "give birth" to ideas, is called:',
   array['Deduction', 'Empiricism', 'Maieutics', 'Hegelian dialectic'],
   'Maieutics ("art of midwifery") helps the other person discover knowledge by themselves, after irony exposes their contradictions.'),
  ('98f987f0-9f05-5749-bc8c-07998c083c27', 'es',
   'El método de Sócrates, basado en preguntas que llevan al interlocutor a reconocer contradicciones y "dar a luz" ideas, se llama:',
   array['Deducción', 'Empirismo', 'Mayéutica', 'Dialéctica hegeliana'],
   'La mayéutica ("arte de partear") ayuda al interlocutor a descubrir por sí mismo el conocimiento, tras exponer la ironía sus contradicciones.'),
  ('bc13e5d0-ed07-5357-8cbf-a44fbc3cd323', 'en',
   'The Sophists, who taught in Athens for a fee, were known above all for:',
   array['Holding that truth comes only from divine revelation', 'Teaching rhetoric and the art of arguing and persuading', 'Living apart from political life', 'Studying nature exclusively'],
   'The Sophists taught oratory and argument to citizens who wanted to take part in the political life of the polis.'),
  ('bc13e5d0-ed07-5357-8cbf-a44fbc3cd323', 'es',
   'Los sofistas, que enseñaban en Atenas a cambio de un pago, eran conocidos sobre todo por:',
   array['Defender que la verdad solo viene de la revelación divina', 'Enseñar retórica y el arte de argumentar y persuadir', 'Vivir aislados de la vida política', 'Estudiar exclusivamente la naturaleza'],
   'Los sofistas enseñaban oratoria y argumentación a los ciudadanos que querían participar en la vida política de la polis.'),
  ('7d224e75-c8fc-57e8-a321-3c625eb8a8a6', 'en',
   'Protagoras'' saying "man is the measure of all things" expresses a position that is:',
   array['Dogmatic, asserting absolute truths', 'Mystical, based on revelations', 'Materialist, based on atoms', 'Relativist, in which truth depends on who perceives and judges'],
   'For Protagoras, things are to each person as they appear to them; there would be no absolute truth independent of human beings.'),
  ('7d224e75-c8fc-57e8-a321-3c625eb8a8a6', 'es',
   'La frase de Protágoras "el hombre es la medida de todas las cosas" expresa una posición:',
   array['Dogmática, que afirma verdades absolutas', 'Mística, basada en revelaciones', 'Materialista, basada en los átomos', 'Relativista, en la que la verdad depende de quien percibe y juzga'],
   'Para Protágoras, las cosas son para cada uno como le aparecen; no habría una verdad absoluta independiente del ser humano.'),
  ('39810917-ea73-5b28-a9d0-bc0ac2a10ca4', 'en',
   'Socrates was sentenced to death in Athens (399 BC) on the charge of:',
   array['Corrupting the youth and not recognizing the city''s gods', 'Betraying Athens in favor of Sparta', 'Stealing the public treasury', 'Writing forbidden books'],
   'The charge was impiety and corrupting the young; Socrates accepted the sentence and drank the hemlock.'),
  ('39810917-ea73-5b28-a9d0-bc0ac2a10ca4', 'es',
   'Sócrates fue condenado a muerte en Atenas (399 a. C.) bajo la acusación de:',
   array['Corromper a la juventud y no reconocer a los dioses de la ciudad', 'Traicionar a Atenas en favor de Esparta', 'Robar el tesoro público', 'Escribir libros prohibidos'],
   'La acusación era de impiedad y de corromper a los jóvenes; Sócrates aceptó la pena y bebió la cicuta.'),
  ('ef13c28a-e9d1-5936-b760-a0dae50cd829', 'en',
   'A fundamental difference between Socrates and the Sophists is that Socrates:',
   array['Charged more for his lessons', 'Held that truth is relative to each person', 'Sought universal definitions (such as that of justice) instead of just winning debates', 'Refused to talk with citizens'],
   'Socrates charged nothing and sought the universal concept of the virtues; he criticized rhetoric used only to persuade.'),
  ('ef13c28a-e9d1-5936-b760-a0dae50cd829', 'es',
   'Una diferencia fundamental entre Sócrates y los sofistas es que Sócrates:',
   array['Cobraba más caro por sus clases', 'Defendía que la verdad es relativa a cada persona', 'Buscaba definiciones universales (como la de lo justo) en lugar de solo ganar debates', 'Se negaba a conversar con los ciudadanos'],
   'Sócrates no cobraba y buscaba el concepto universal de las virtudes; criticaba la retórica usada solo para persuadir.'),
  ('922019e9-836c-589f-9a63-9879723359fb', 'en',
   'In Plato''s theory, true reality, eternal and unchanging, lies in the:',
   array['Sensible world', 'World of Ideas (or Forms)', 'World of atoms', 'World of dreams'],
   'For Plato, the sensible world is an imperfect, changing copy; the Ideas are eternal models, reached by reason.'),
  ('922019e9-836c-589f-9a63-9879723359fb', 'es',
   'En la teoría de Platón, la verdadera realidad, eterna e inmutable, está en el:',
   array['Mundo sensible', 'Mundo de las Ideas (o Formas)', 'Mundo de los átomos', 'Mundo de los sueños'],
   'Para Platón, el mundo sensible es copia imperfecta y cambiante; las Ideas son modelos eternos, alcanzados por la razón.'),
  ('05a349d5-e01a-5ed4-83c4-cee7533b0a88', 'en',
   'In Plato''s Allegory of the Cave, the shadows cast on the wall represent:',
   array['The perfect Ideas', 'Philosophical knowledge', 'The Sun and the Good', 'The appearances and opinions of the sensible world'],
   'The prisoners take the shadows for reality: such are opinions (doxa) based on the senses.'),
  ('05a349d5-e01a-5ed4-83c4-cee7533b0a88', 'es',
   'En el Mito de la Caverna, de Platón, las sombras proyectadas en la pared representan:',
   array['Las Ideas perfectas', 'El conocimiento filosófico', 'El Sol y el Bien', 'Las apariencias y opiniones del mundo sensible'],
   'Los prisioneros toman las sombras por realidad: así son las opiniones (doxa) basadas en los sentidos.'),
  ('0f1e3f81-504f-5914-82f5-2695308e179d', 'en',
   'In The Republic, Plato argues that the just city should be ruled by:',
   array['Philosophers, who know the Good', 'Warriors, the strongest', 'Merchants, the richest', 'All citizens chosen by lot'],
   'For Plato, only those who contemplate the Idea of the Good know how to rule justly: the philosopher-king.'),
  ('0f1e3f81-504f-5914-82f5-2695308e179d', 'es',
   'En La República, Platón defiende que la ciudad justa debería ser gobernada por:',
   array['Filósofos, que conocen el Bien', 'Guerreros, los más fuertes', 'Comerciantes, los más ricos', 'Todos los ciudadanos por sorteo'],
   'Para Platón, solo quien contempla la Idea del Bien sabe gobernar con justicia: el rey filósofo.'),
  ('bf6fbe7e-1946-58e9-95f9-e638c6d307f9', 'en',
   'Plato''s theory of recollection states that knowing is:',
   array['Recording sensations as on a blank slate', 'Creating new ideas out of nothing', 'Remembering what the soul already contemplated in the world of Ideas', 'Accepting the majority''s opinion'],
   'For Plato, the soul contemplated the Ideas before being embodied; learning is remembering (anamnesis).'),
  ('bf6fbe7e-1946-58e9-95f9-e638c6d307f9', 'es',
   'La teoría de la reminiscencia, de Platón, afirma que conocer es:',
   array['Registrar las sensaciones como en una hoja en blanco', 'Crear ideas nuevas a partir de la nada', 'Recordar lo que el alma ya contempló en el mundo de las Ideas', 'Aceptar la opinión de la mayoría'],
   'Para Platón, el alma ya contempló las Ideas antes de encarnarse; aprender es recordar (anámnesis).'),
  ('91574d34-b188-51bd-a4cd-0b40ef1f9a94', 'en',
   'In Plato''s division of the soul, the part that should govern the others is the:',
   array['Appetitive (of desires)', 'Rational', 'Spirited (of courage)', 'Vegetative'],
   'For Plato, the just soul is one in which reason rules, the spirited part helps it and desires are moderated.'),
  ('91574d34-b188-51bd-a4cd-0b40ef1f9a94', 'es',
   'En la división platónica del alma, la parte que debe gobernar a las demás es la:',
   array['Concupiscible (de los deseos)', 'Racional', 'Irascible (del coraje)', 'Vegetativa'],
   'Para Platón, el alma justa es aquella en que la razón gobierna, la parte irascible la auxilia y los deseos se moderan.'),
  ('08485102-4113-5348-9acb-315779ab68eb', 'en',
   'The work Apology of Socrates, written by Plato, presents:',
   array['A treatise on the physics of the four elements', 'The ideal laws of an imaginary city', 'A dialogue about love at a banquet', 'Socrates'' defense before the court that condemned him'],
   'In the Apology, Plato reconstructs Socrates'' defense speech at the trial of 399 BC.'),
  ('08485102-4113-5348-9acb-315779ab68eb', 'es',
   'La obra Apología de Sócrates, escrita por Platón, presenta:',
   array['Un tratado sobre la física de los cuatro elementos', 'Las leyes ideales de una ciudad imaginaria', 'Un diálogo sobre el amor en un banquete', 'La defensa de Sócrates ante el tribunal que lo condenó'],
   'En la Apología, Platón reconstruye el discurso de defensa de Sócrates en el juicio del 399 a. C.'),
  ('fa9e1d8c-f5c6-5399-9ab9-6f78ea281700', 'en',
   'Aristotle was a student of:',
   array['Socrates', 'Thales', 'Plato', 'Heraclitus'],
   'Aristotle studied for about 20 years at Plato''s Academy and later founded his own school, the Lyceum.'),
  ('fa9e1d8c-f5c6-5399-9ab9-6f78ea281700', 'es',
   'Aristóteles fue alumno de:',
   array['Sócrates', 'Tales', 'Platón', 'Heráclito'],
   'Aristóteles estudió unos 20 años en la Academia de Platón y luego fundó su propia escuela, el Liceo.'),
  ('d3788f75-2ef9-53e1-928e-3ae16f6ff2e6', 'en',
   'Aristotle defined the human being as a "political animal", meaning that humans:',
   array['Naturally live in community, in the polis', 'Must be ruled by kings', 'Are born with no rational capacity', 'Live better isolated from society'],
   'For Aristotle, humans fulfill their nature in community life, using language and reason.'),
  ('d3788f75-2ef9-53e1-928e-3ae16f6ff2e6', 'es',
   'Aristóteles definió al ser humano como un "animal político", lo que significa que:',
   array['Vive naturalmente en comunidad, en la polis', 'Debe ser gobernado por reyes', 'Nace sin ninguna capacidad racional', 'Vive mejor aislado de la sociedad'],
   'Para Aristóteles, el ser humano realiza su naturaleza en la vida en comunidad, usando el lenguaje y la razón.'),
  ('8abf746a-6516-5de5-a76c-5076713fe5c7', 'en',
   'In Aristotle''s ethics, virtue is understood as:',
   array['The maximum pleasure in each action', 'Blind obedience to divine laws', 'The renunciation of all desires', 'The right mean between two extremes (excess and deficiency)'],
   'Virtue is the mean: courage, for example, lies between cowardice (deficiency) and rashness (excess).'),
  ('8abf746a-6516-5de5-a76c-5076713fe5c7', 'es',
   'En la ética de Aristóteles, la virtud se entiende como:',
   array['El placer máximo en cada acción', 'La obediencia ciega a las leyes divinas', 'La renuncia a todos los deseos', 'El justo medio entre dos extremos (exceso y defecto)'],
   'La virtud es el término medio: el coraje, por ejemplo, está entre la cobardía (defecto) y la temeridad (exceso).'),
  ('342b8f56-e898-5926-9e50-91716081a50b', 'en',
   'For Aristotle, the ultimate goal of human life is:',
   array['Wealth', 'Eudaimonia (happiness or a flourishing life)', 'Fame', 'Contemplation of the Olympian gods'],
   'Eudaimonia is the highest good, sought for its own sake, reached through a virtuous life according to reason.'),
  ('342b8f56-e898-5926-9e50-91716081a50b', 'es',
   'Para Aristóteles, la finalidad última de la vida humana es la:',
   array['Riqueza', 'Eudaimonía (felicidad o vida plena)', 'Fama', 'Contemplación de los dioses olímpicos'],
   'La eudaimonía es el bien supremo, buscado por sí mismo, alcanzado por la vida virtuosa según la razón.'),
  ('8a23dec7-9267-5c9d-85b7-b60004f4b480', 'en',
   'In Aristotle''s theory of the four causes, the final cause of a statue is:',
   array['The purpose for which it was made', 'The marble it is made of', 'The sculptor who produced it', 'The shape it has'],
   'The four causes are material (marble), formal (shape), efficient (sculptor) and final (the purpose, the "what for").'),
  ('8a23dec7-9267-5c9d-85b7-b60004f4b480', 'es',
   'En la teoría de las cuatro causas de Aristóteles, la causa final de una estatua es:',
   array['El propósito para el cual fue hecha', 'El mármol del que está hecha', 'El escultor que la produjo', 'La forma que tiene'],
   'Las cuatro causas son material (mármol), formal (forma), eficiente (escultor) y final (la finalidad, el "para qué").'),
  ('df033dae-d25e-5173-867f-6067e5e676ff', 'en',
   'Unlike Plato, Aristotle claimed that the form (essence) of things:',
   array['Exists only in a separate world of Ideas', 'Is an illusion of the senses', 'Exists in the things themselves, united with matter', 'Can only be known by divine revelation'],
   'For Aristotle, form and matter are inseparable in concrete beings; there is no separate world of Ideas.'),
  ('df033dae-d25e-5173-867f-6067e5e676ff', 'es',
   'A diferencia de Platón, Aristóteles afirmaba que la forma (esencia) de las cosas:',
   array['Existe solo en un mundo separado de las Ideas', 'Es una ilusión de los sentidos', 'Existe en las propias cosas, unida a la materia', 'Solo puede conocerse por revelación divina'],
   'Para Aristóteles, forma y materia son inseparables en los seres concretos; no hay un mundo de las Ideas aparte.'),
  ('49eb67da-1ac9-5181-aba4-478dd63e2d7f', 'en',
   'For Epicurus, happiness consists mainly in:',
   array['Accumulating wealth and power', 'Reaching ataraxia (peace of mind) and the absence of pain', 'Blindly obeying fate', 'Seeking every intense pleasure without limit'],
   'Epicurean pleasure is moderate: absence of pain in the body (aponia) and of disturbance in the soul (ataraxia).'),
  ('49eb67da-1ac9-5181-aba4-478dd63e2d7f', 'es',
   'Para Epicuro, la felicidad consiste principalmente en:',
   array['Acumular riquezas y poder', 'Alcanzar la ataraxia (tranquilidad del alma) y la ausencia de dolor', 'Obedecer ciegamente al destino', 'Buscar todos los placeres intensos sin límite'],
   'El placer epicúreo es moderado: ausencia de dolor en el cuerpo (aponía) y de perturbación en el alma (ataraxia).'),
  ('21fe0bf4-68f5-5670-80e1-32e13459170d', 'en',
   'The Stoics taught that, to live well, one must:',
   array['Flee from all responsibilities', 'Seek fame at any cost', 'Live according to nature and accept what does not depend on us', 'Doubt the existence of the world'],
   'For Stoicism, the wise person distinguishes what is under their control and calmly accepts the rest.'),
  ('21fe0bf4-68f5-5670-80e1-32e13459170d', 'es',
   'Los estoicos enseñaban que, para vivir bien, es preciso:',
   array['Huir de todas las responsabilidades', 'Buscar la fama a cualquier costo', 'Vivir de acuerdo con la naturaleza y aceptar lo que no depende de nosotros', 'Dudar de la existencia del mundo'],
   'Para el estoicismo, sabio es quien distingue lo que está bajo su control y acepta con serenidad lo demás.'),
  ('3976ea5c-70bd-55ea-9cfa-49b9dfdfc449', 'en',
   'The Skeptics, like Pyrrho, recommended suspending judgment (epoché) because:',
   array['For every argument there is another of equal strength, and certainty cannot be reached', 'Truth lies in sacred books', 'Only the senses give absolute certainty', 'Reason proves everything that exists'],
   'Faced with equally strong reasons, the skeptic suspends judgment and thereby seeks tranquility.'),
  ('3976ea5c-70bd-55ea-9cfa-49b9dfdfc449', 'es',
   'Los escépticos, como Pirrón, recomendaban la suspensión del juicio (epojé) porque:',
   array['Para todo argumento hay otro de igual fuerza, y no se puede alcanzar certeza', 'La verdad está en los libros sagrados', 'Solo los sentidos dan certeza absoluta', 'La razón prueba todo lo que existe'],
   'Ante razones equivalentes, el escéptico suspende el juicio y busca así la tranquilidad.'),
  ('c7046610-83cf-5a9e-bd58-84c78900a0a6', 'en',
   'Diogenes of Sinope, who lived in a barrel and scorned social conventions, belonged to the school of the:',
   array['Stoics', 'Epicureans', 'Skeptics', 'Cynics'],
   'The Cynics advocated a simple life according to nature, rejecting wealth and conventions.'),
  ('c7046610-83cf-5a9e-bd58-84c78900a0a6', 'es',
   'Diógenes de Sinope, que vivía en un barril y despreciaba las convenciones sociales, pertenecía a la escuela:',
   array['Estoica', 'Epicúrea', 'Escéptica', 'Cínica'],
   'Los cínicos defendían una vida sencilla, según la naturaleza, rechazando riquezas y convenciones.'),
  ('9806c6b7-8b10-5ac3-9474-6e6af73bfc6e', 'en',
   'The Hellenistic schools emerged in a context marked by:',
   array['The height of Athenian democracy', 'The end of the polis'' autonomy and the rise of large empires after Alexander', 'The fall of the Western Roman Empire', 'The Protestant Reformation'],
   'With Alexander''s conquests, the polis loses autonomy; philosophy turns to the search for individual tranquility.'),
  ('9806c6b7-8b10-5ac3-9474-6e6af73bfc6e', 'es',
   'Las escuelas helenísticas surgieron en un contexto marcado:',
   array['Por el auge de la democracia ateniense', 'Por el fin de la autonomía de las polis y la formación de grandes imperios tras Alejandro', 'Por la caída del Imperio romano de Occidente', 'Por la Reforma protestante'],
   'Con las conquistas de Alejandro, la polis pierde autonomía; la filosofía se vuelca a la búsqueda de la tranquilidad individual.'),
  ('47f9d228-ddcb-58cd-80e9-28bf3ef203d6', 'en',
   'Epicurus'' argument that "death is nothing to us" is based on the idea that:',
   array['The soul is immortal and will be judged by the gods', 'Death is a punishment for life''s mistakes', 'The gods control human fate', 'When death is present, we are not, and there is no sensation after it'],
   'Since everything is sensation and death is the end of sensation, there is no reason to fear it.'),
  ('47f9d228-ddcb-58cd-80e9-28bf3ef203d6', 'es',
   'El argumento de Epicuro de que "la muerte no es nada para nosotros" se basa en la idea de que:',
   array['El alma es inmortal y será juzgada por los dioses', 'La muerte es un castigo por los errores de la vida', 'Los dioses controlan el destino humano', 'Cuando la muerte está presente, nosotros no estamos, y no hay sensación después de ella'],
   'Como todo es sensación y la muerte es el fin de la sensación, no hay por qué temerla.'),
  ('0ff698b4-425e-5e54-9013-c31fda96a780', 'en',
   'A central theme of medieval philosophy was the relationship between:',
   array['Faith and reason', 'Atoms and the void', 'Capital and labor', 'Myth and logos'],
   'Medieval thinkers sought to reconcile Christian faith with the philosophical reason inherited from the Greeks.'),
  ('0ff698b4-425e-5e54-9013-c31fda96a780', 'es',
   'Un tema central de la filosofía medieval fue la relación entre:',
   array['Fe y razón', 'Átomos y vacío', 'Capital y trabajo', 'Mito y logos'],
   'Los pensadores medievales buscaron conciliar la fe cristiana con la razón filosófica heredada de los griegos.'),
  ('a03e60b9-ee8b-50f0-a7e6-ab1d86ad16ca', 'en',
   'Saint Augustine, the main name of Patristics, was strongly influenced by the philosophy of:',
   array['Aristotle', 'Epicurus', 'Plato', 'Democritus'],
   'Augustine brought Christianity close to Platonic thought (through Neoplatonism).'),
  ('a03e60b9-ee8b-50f0-a7e6-ab1d86ad16ca', 'es',
   'San Agustín, principal nombre de la Patrística, fue fuertemente influido por la filosofía de:',
   array['Aristóteles', 'Epicuro', 'Platón', 'Demócrito'],
   'Agustín acercó el cristianismo al pensamiento platónico (a través del neoplatonismo).'),
  ('19321bc2-f00d-53e0-8303-b850d9f15a71', 'en',
   'Saint Thomas Aquinas, the main name of Scholasticism, sought to reconcile Christian faith with the philosophy of:',
   array['Plato', 'Aristotle', 'Heraclitus', 'Pythagoras'],
   'Thomas Aquinas integrated Aristotelian thought into Christian theology, for example in the Five Ways.'),
  ('19321bc2-f00d-53e0-8303-b850d9f15a71', 'es',
   'Santo Tomás de Aquino, principal nombre de la Escolástica, buscó conciliar la fe cristiana con la filosofía de:',
   array['Platón', 'Aristóteles', 'Heráclito', 'Pitágoras'],
   'Tomás de Aquino integró el pensamiento aristotélico a la teología cristiana, por ejemplo en las Cinco Vías.'),
  ('3c5f648c-4161-5a8a-80f1-4e741049ffa2', 'en',
   'For Saint Augustine, evil:',
   array['Is a substance created by God', 'Is a force equal and opposite to God', 'Does not exist in the world at all', 'Is the absence (privation) of good, linked to the misuse of free will'],
   'Augustine defines evil as privation of good; moral evil arises from the misuse of human freedom.'),
  ('3c5f648c-4161-5a8a-80f1-4e741049ffa2', 'es',
   'Para San Agustín, el mal:',
   array['Es una sustancia creada por Dios', 'Es una fuerza igual y opuesta a Dios', 'No existe de ninguna manera en el mundo', 'Es ausencia (privación) del bien, ligada al mal uso del libre albedrío'],
   'Agustín define el mal como privación del bien; el mal moral nace del mal uso de la libertad humana.'),
  ('c2269299-758b-5a05-945e-d1cce0f92f02', 'en',
   'Thomas Aquinas'' "Five Ways" are:',
   array['Rational arguments to demonstrate the existence of God', 'Rules for monastic life', 'Steps of the modern scientific method', 'Criticisms of the Catholic Church'],
   'In the Five Ways (first mover, first cause, necessary being etc.), Thomas argues rationally for the existence of God.'),
  ('c2269299-758b-5a05-945e-d1cce0f92f02', 'es',
   'Las "Cinco Vías" de Tomás de Aquino son:',
   array['Argumentos racionales para demostrar la existencia de Dios', 'Reglas para la vida monástica', 'Etapas del método científico moderno', 'Críticas a la Iglesia católica'],
   'En las Cinco Vías (primer motor, causa primera, ser necesario, etc.), Tomás argumenta racionalmente a favor de la existencia de Dios.'),
  ('21e8419b-b0c7-55de-92fe-605f22563cda', 'en',
   'The so-called "problem of universals" debated:',
   array['Whether the Earth is at the center of the universe', 'Who should be pope', 'Whether general concepts (such as "humanity") really exist or are just names', 'Whether the Bible should be translated'],
   'Realists claimed that universals exist; nominalists, such as William of Ockham, that they are only names.'),
  ('21e8419b-b0c7-55de-92fe-605f22563cda', 'es',
   'La llamada "querella de los universales" discutía:',
   array['Si la Tierra está en el centro del universo', 'Quién debía ser el papa', 'Si los conceptos generales (como "humanidad") existen de hecho o son solo nombres', 'Si la Biblia debía traducirse'],
   'Los realistas afirmaban que los universales existen; los nominalistas, como Guillermo de Ockham, que son solo nombres.'),
  ('d2f13a7c-7f28-5f16-b122-9e1f3506a6d6', 'en',
   'The phrase "I think, therefore I am" is by:',
   array['John Locke', 'René Descartes', 'David Hume', 'Immanuel Kant'],
   'Descartes arrives at the cogito: even doubting everything, the existence of the one who thinks is indubitable.'),
  ('d2f13a7c-7f28-5f16-b122-9e1f3506a6d6', 'es',
   'La frase "Pienso, luego existo" es de:',
   array['John Locke', 'René Descartes', 'David Hume', 'Immanuel Kant'],
   'Descartes llega al cogito: aun dudando de todo, la existencia de quien piensa es indudable.'),
  ('ca0d0075-c6f1-5ca4-abe2-db4fb502c98e', 'en',
   'For the rationalists, the main source of reliable knowledge is:',
   array['Tradition', 'Sense experience', 'Religious revelation', 'Reason'],
   'Rationalism (Descartes, Spinoza, Leibniz) considers reason the source of certain and universal knowledge.'),
  ('ca0d0075-c6f1-5ca4-abe2-db4fb502c98e', 'es',
   'Para los racionalistas, la principal fuente del conocimiento seguro es:',
   array['La tradición', 'La experiencia sensible', 'La revelación religiosa', 'La razón'],
   'El racionalismo (Descartes, Spinoza, Leibniz) considera la razón la fuente del conocimiento cierto y universal.'),
  ('891b4094-a9f6-5800-b78a-07ae783ecef8', 'en',
   'Descartes'' methodical doubt consists in:',
   array['Doubting everything forever, without reaching any certainty', 'Accepting only what the senses show', 'Doubting everything that can be doubted, in order to find an indubitable truth', 'Trusting the opinions of the ancients'],
   'Cartesian doubt is a method, not an end: it serves to reach a first secure certainty (the cogito).'),
  ('891b4094-a9f6-5800-b78a-07ae783ecef8', 'es',
   'La duda metódica de Descartes consiste en:',
   array['Dudar de todo para siempre, sin llegar a ninguna certeza', 'Aceptar solo lo que muestran los sentidos', 'Dudar de todo lo que pueda ponerse en duda, para encontrar una verdad indudable', 'Confiar en las opiniones de los antiguos'],
   'La duda cartesiana es un método, no un fin: sirve para llegar a una primera certeza segura (el cogito).'),
  ('50e29685-f593-5b63-a003-498bc4048cf2', 'en',
   'Descartes divided reality into two substances, thinking and extended. This position is called:',
   array['Dualism', 'Materialism', 'Monism', 'Skepticism'],
   'Cartesian dualism separates res cogitans (mind, thought) and res extensa (body, matter).'),
  ('50e29685-f593-5b63-a003-498bc4048cf2', 'es',
   'Descartes dividió la realidad en dos sustancias, la pensante y la extensa. Esta posición se llama:',
   array['Dualismo', 'Materialismo', 'Monismo', 'Escepticismo'],
   'El dualismo cartesiano separa res cogitans (mente, pensamiento) y res extensa (cuerpo, materia).'),
  ('d321e282-1a63-5460-911d-e58959577219', 'en',
   'For Descartes, innate ideas are those that:',
   array['Come from the senses after birth', 'Are invented by the imagination', 'Are taught by society', 'Are already in the mind, like the idea of God and mathematical truths'],
   'Descartes distinguishes adventitious ideas (from the senses), fictitious (imagination) and innate (present in reason).'),
  ('d321e282-1a63-5460-911d-e58959577219', 'es',
   'Para Descartes, las ideas innatas son aquellas que:',
   array['Vienen de los sentidos después del nacimiento', 'Son inventadas por la imaginación', 'Son enseñadas por la sociedad', 'Ya están en la mente, como la idea de Dios y las verdades matemáticas'],
   'Descartes distingue ideas adventicias (de los sentidos), ficticias (imaginación) e innatas (presentes en la razón).'),
  ('ceb041b6-0e93-5958-94c9-0ce505e08d11', 'en',
   'Spinoza, a 17th-century rationalist, identified God with:',
   array['A personal being separate from the world', 'Nature itself (Deus sive Natura)', 'Aristotle''s unmoved mover', 'The will of the sovereign'],
   'For Spinoza there is a single substance, God or Nature; everything that exists is a mode of this substance.'),
  ('ceb041b6-0e93-5958-94c9-0ce505e08d11', 'es',
   'Spinoza, racionalista del siglo XVII, identificó a Dios con:',
   array['Un ser personal separado del mundo', 'La propia naturaleza (Deus sive Natura)', 'El primer motor inmóvil de Aristóteles', 'La voluntad del soberano'],
   'Para Spinoza hay una única sustancia, Dios o Naturaleza; todo lo que existe es modo de esa sustancia.'),
  ('f6f7ea15-eaba-5a52-92ec-b7ca0eb5bde9', 'en',
   'For the empiricists, all knowledge originates in:',
   array['Pure reason', 'Divine revelation', 'Sense experience', 'Mystical intuition'],
   'Empiricism (Locke, Berkeley, Hume) states that knowledge comes from experience.'),
  ('f6f7ea15-eaba-5a52-92ec-b7ca0eb5bde9', 'es',
   'Para los empiristas, todo conocimiento tiene origen en la:',
   array['Razón pura', 'Revelación divina', 'Experiencia sensible', 'Intuición mística'],
   'El empirismo (Locke, Berkeley, Hume) afirma que el conocimiento viene de la experiencia.'),
  ('bba4eb7e-9131-5bda-aba5-fb9aeee2c452', 'en',
   'John Locke compared the human mind at birth to:',
   array['A blank slate (tabula rasa)', 'A complete library', 'A perfect mirror', 'A calculating machine'],
   'For Locke there are no innate ideas: the mind starts empty and is filled by experience.'),
  ('bba4eb7e-9131-5bda-aba5-fb9aeee2c452', 'es',
   'John Locke comparó la mente humana, al nacer, con:',
   array['Una hoja en blanco (tabula rasa)', 'Una biblioteca completa', 'Un espejo perfecto', 'Una máquina de calcular'],
   'Para Locke no hay ideas innatas: la mente empieza vacía y la experiencia la va llenando.'),
  ('4a1e4ac3-9f8b-5bb2-8764-57a35abf64bd', 'en',
   'David Hume criticized the idea of causation by stating that it is based:',
   array['On mathematical proofs', 'On innate ideas', 'On divine revelation', 'On the habit of seeing events follow one another, not on a perceived necessary connection'],
   'We see one event follow another repeatedly and, by habit, expect it to continue; the necessity is not observed.'),
  ('4a1e4ac3-9f8b-5bb2-8764-57a35abf64bd', 'es',
   'David Hume criticó la idea de causalidad afirmando que se basa:',
   array['En demostraciones matemáticas', 'En ideas innatas', 'En la revelación divina', 'En el hábito de ver sucederse los hechos, y no en una conexión necesaria percibida'],
   'Vemos que un hecho sigue a otro repetidamente y, por hábito, esperamos que continúe; la necesidad no se observa.'),
  ('2380222e-eafc-528e-adcf-9b00fa4c0660', 'en',
   'The phrase "to be is to be perceived" (esse est percipi) sums up the philosophy of:',
   array['John Locke', 'George Berkeley', 'Francis Bacon', 'Thomas Hobbes'],
   'For Berkeley, things exist only as long as they are perceived (by us or by God).'),
  ('2380222e-eafc-528e-adcf-9b00fa4c0660', 'es',
   'La frase "ser es ser percibido" (esse est percipi) resume la filosofía de:',
   array['John Locke', 'George Berkeley', 'Francis Bacon', 'Thomas Hobbes'],
   'Para Berkeley, las cosas solo existen en tanto son percibidas (por nosotros o por Dios).'),
  ('a1344253-c467-5d4d-ac01-e367d953aec8', 'en',
   'Francis Bacon called "idols" the:',
   array['Gods of ancient religions', 'Rulers who abuse power', 'Prejudices and errors of the mind that hinder true knowledge', 'Mathematical methods of inquiry'],
   'Bacon describes idols of the tribe, the cave, the marketplace and the theater, which distort knowledge.'),
  ('a1344253-c467-5d4d-ac01-e367d953aec8', 'es',
   'Francis Bacon llamó "ídolos" a los:',
   array['Dioses de las religiones antiguas', 'Gobernantes que abusan del poder', 'Prejuicios y errores de la mente que estorban el conocimiento verdadero', 'Métodos matemáticos de investigación'],
   'Bacon describe los ídolos de la tribu, de la caverna, del foro (mercado) y del teatro, que distorsionan el conocimiento.'),
  ('d83a2894-5ca1-5a02-a9b9-76961466883d', 'en',
   'The so-called "problem of induction", formulated by Hume, questions:',
   array['How to justify general conclusions from observed particular cases', 'How to prove geometric theorems', 'Why governments should exist', 'How to distinguish the beautiful from the ugly'],
   'Observing many cases does not logically guarantee the next will be the same; induction lacks full rational justification.'),
  ('d83a2894-5ca1-5a02-a9b9-76961466883d', 'es',
   'El llamado "problema de la inducción", formulado por Hume, cuestiona:',
   array['Cómo justificar conclusiones generales a partir de casos particulares observados', 'Cómo probar teoremas geométricos', 'Por qué deben existir los gobiernos', 'Cómo distinguir lo bello de lo feo'],
   'Observar muchos casos no garantiza lógicamente que el próximo será igual; la inducción no tiene plena justificación racional.'),
  ('23da65ac-8809-52bd-b541-3e7ecc800787', 'en',
   'For Kant, Enlightenment is humanity''s emergence from:',
   array['Life in the countryside', 'Immaturity, that is, the inability to use one''s own understanding without another''s guidance', 'The Christian religion', 'Absolute monarchy'],
   'In "What is Enlightenment?", Kant urges: "Dare to know! Have the courage to use your own understanding".'),
  ('23da65ac-8809-52bd-b541-3e7ecc800787', 'es',
   'Para Kant, la Ilustración es la salida del ser humano de la:',
   array['Vida en el campo', 'Minoría de edad, es decir, la incapacidad de usar el propio entendimiento sin la guía de otro', 'Religión cristiana', 'Monarquía absoluta'],
   'En "¿Qué es la Ilustración?", Kant invita: "¡Atrévete a saber! Ten el valor de servirte de tu propio entendimiento".'),
  ('1b2e50f2-0192-5979-a95d-565120da63a9', 'en',
   'Kant''s categorical imperative commands us to act:',
   array['Always seeking the greatest pleasure', 'According to what the majority approves', 'According to the laws of the State, without exception', 'Only according to a maxim that you can will to become a universal law'],
   'An action is moral when its maxim can be universalized, done out of duty and not out of interest.'),
  ('1b2e50f2-0192-5979-a95d-565120da63a9', 'es',
   'El imperativo categórico de Kant manda actuar:',
   array['Buscando siempre el mayor placer', 'Conforme a lo que aprueba la mayoría', 'De acuerdo con las leyes del Estado, sin excepción', 'Solo según una máxima que puedas querer que se convierta en ley universal'],
   'La acción es moral cuando su máxima puede universalizarse, hecha por deber y no por interés.'),
  ('a2d4f29a-8724-5835-a753-e1444eca4e49', 'en',
   'Kant is known for proposing a synthesis between:',
   array['Rationalism and empiricism', 'Epicureanism and Stoicism', 'Platonism and atomism', 'Christianity and Islam'],
   'For Kant, knowledge begins with experience, but not all of it comes from experience: reason contributes forms and categories.'),
  ('a2d4f29a-8724-5835-a753-e1444eca4e49', 'es',
   'Kant es conocido por proponer una síntesis entre:',
   array['Racionalismo y empirismo', 'Epicureísmo y estoicismo', 'Platonismo y atomismo', 'Cristianismo e islam'],
   'Para Kant, el conocimiento empieza con la experiencia, pero no todo en él procede de ella: la razón aporta formas y categorías.'),
  ('88623ea5-5c0b-55f5-9e43-f9996a11f818', 'en',
   'Kant''s so-called "Copernican revolution" in the theory of knowledge states that:',
   array['The Earth revolves around the Sun', 'Knowledge depends only on objects', 'Objects conform to the structures of the knowing subject', 'Only God can know reality'],
   'Instead of the subject adapting to the object, the known object conforms to the forms of sensibility and the categories of understanding.'),
  ('88623ea5-5c0b-55f5-9e43-f9996a11f818', 'es',
   'La llamada "revolución copernicana" de Kant en la teoría del conocimiento afirma que:',
   array['La Tierra gira alrededor del Sol', 'El conocimiento depende solo de los objetos', 'Los objetos se rigen por las estructuras del sujeto que conoce', 'Solo Dios puede conocer la realidad'],
   'En lugar de que el sujeto se adapte al objeto, el objeto conocido se adapta a las formas de la sensibilidad y a las categorías del entendimiento.'),
  ('bc920f54-9919-5eda-ae0b-05438803d533', 'en',
   'Kant distinguishes phenomenon from noumenon. The noumenon (thing in itself) is:',
   array['What appears to our senses', 'Reality as it is in itself, which we cannot know', 'One of Descartes'' innate ideas', 'A mathematical concept'],
   'We only know phenomena (things as they appear to us); the thing in itself can be thought but not known.'),
  ('bc920f54-9919-5eda-ae0b-05438803d533', 'es',
   'Kant distingue el fenómeno del noúmeno. El noúmeno (cosa en sí) es:',
   array['Aquello que aparece a nuestros sentidos', 'La realidad tal como es en sí misma, que no podemos conocer', 'Una idea innata de Descartes', 'Un concepto matemático'],
   'Solo conocemos los fenómenos (las cosas como nos aparecen); la cosa en sí puede pensarse, pero no conocerse.'),
  ('6380ed68-8753-569b-9882-ce3e95551f2f', 'en',
   'One formulation of the categorical imperative says we must treat humanity:',
   array['As a means to reach general happiness', 'According to each person''s usefulness', 'According to the ruler''s will', 'Always as an end, and never merely as a means'],
   'The formula of humanity requires respecting people''s dignity: no one may be used merely as an instrument.'),
  ('6380ed68-8753-569b-9882-ce3e95551f2f', 'es',
   'Una de las formulaciones del imperativo categórico dice que debemos tratar a la humanidad:',
   array['Como medio para alcanzar la felicidad general', 'Según la utilidad de cada persona', 'Según la voluntad del gobernante', 'Siempre como fin, y nunca solo como medio'],
   'La fórmula de la humanidad exige respetar la dignidad de las personas: nadie puede ser usado solo como instrumento.'),
  ('102723c8-5c65-53c2-8a31-ec89d636ff94', 'en',
   'Ethics, as an area of philosophy, is mainly devoted to:',
   array['Studying the stars and the universe', 'Classifying species of living beings', 'Reflecting on values, the good and how we should act', 'Describing how languages were formed'],
   'Ethics investigates the foundations of human action: what is good, just and how we should live.'),
  ('102723c8-5c65-53c2-8a31-ec89d636ff94', 'es',
   'La ética, como área de la filosofía, se dedica principalmente a:',
   array['Estudiar los astros y el universo', 'Clasificar las especies de seres vivos', 'Reflexionar sobre los valores, el bien y cómo debemos actuar', 'Describir la formación de las lenguas'],
   'La ética investiga los fundamentos del actuar humano: qué es bueno, justo y cómo debemos vivir.'),
  ('d6a38d6b-b689-5117-a2e5-d9c753ffe8c0', 'en',
   'A common distinction between morality and ethics is that:',
   array['Morality is a group''s norms and customs; ethics is the critical reflection on those norms', 'Morality deals with nature; ethics with politics', 'Morality and ethics are completely unrelated terms', 'Ethics exists only in religions'],
   'Morality (mores, customs) is the set of rules people live by; ethics examines them and seeks their grounds.'),
  ('d6a38d6b-b689-5117-a2e5-d9c753ffe8c0', 'es',
   'Una distinción común entre moral y ética es que:',
   array['La moral son las normas y costumbres de un grupo; la ética es la reflexión crítica sobre esas normas', 'La moral trata de la naturaleza; la ética, de la política', 'Moral y ética son términos sin ninguna relación', 'La ética solo existe en las religiones'],
   'La moral (mores, costumbres) es el conjunto de reglas vividas; la ética las examina y busca sus fundamentos.'),
  ('7cc71b4b-aef7-5cc1-8d79-bad285150493', 'en',
   'For an action to be morally evaluated, it is assumed that the agent has:',
   array['Enough wealth', 'The majority''s support', 'Advanced scientific knowledge', 'Awareness and freedom to choose'],
   'Moral responsibility is only attributed to those who act with awareness and freedom; forced or ignorant actions reduce blame.'),
  ('7cc71b4b-aef7-5cc1-8d79-bad285150493', 'es',
   'Para que una acción pueda evaluarse moralmente, se presupone que el agente tiene:',
   array['Riqueza suficiente', 'Apoyo de la mayoría', 'Conocimiento científico avanzado', 'Conciencia y libertad para elegir'],
   'Solo se atribuye responsabilidad moral a quien actúa con conciencia y libertad; las acciones forzadas o ignorantes atenúan la culpa.'),
  ('e882e904-27aa-5bad-9aab-c93cdfc73f50', 'en',
   'Moral relativism holds that:',
   array['There is a single morality valid for all peoples', 'Moral values vary according to culture and time', 'Only science defines what is right', 'Natural laws determine all customs'],
   'For relativism, there is no universal moral standard: right and wrong depend on cultural context.'),
  ('e882e904-27aa-5bad-9aab-c93cdfc73f50', 'es',
   'El relativismo moral sostiene que:',
   array['Existe una única moral válida para todos los pueblos', 'Los valores morales varían según la cultura y la época', 'Solo la ciencia define lo que es correcto', 'Las leyes naturales determinan todas las costumbres'],
   'Para el relativismo, no hay un patrón moral universal: lo correcto y lo incorrecto dependen del contexto cultural.'),
  ('0c5d21f4-b31c-512b-846d-19a6ec8b5d2f', 'en',
   'In bioethics debates, such as on euthanasia or cloning, philosophy contributes mainly by:',
   array['Providing ready-made, indisputable answers', 'Replacing current legislation', 'Analyzing the arguments and principles involved, such as autonomy and dignity', 'Banning any scientific progress'],
   'Bioethics examines the dilemmas raised by science in light of principles such as autonomy, beneficence and justice.'),
  ('0c5d21f4-b31c-512b-846d-19a6ec8b5d2f', 'es',
   'En debates de bioética, como sobre la eutanasia o la clonación, la filosofía contribuye principalmente al:',
   array['Dar respuestas listas e indiscutibles', 'Sustituir la legislación vigente', 'Analizar los argumentos y principios implicados, como autonomía y dignidad', 'Prohibir cualquier avance científico'],
   'La bioética examina los dilemas planteados por la ciencia a la luz de principios como autonomía, beneficencia y justicia.'),
  ('8d399448-3acd-538d-8687-ff57682ec60a', 'en',
   'The so-called "trolley problem", in which one decides to divert a vehicle to save five people by sacrificing one, is used to discuss:',
   array['The conflict between calculating consequences and respecting duties or individual rights', 'The physical laws of motion', 'The history of public transport', 'The mythical origin of the world'],
   'The dilemma sets consequentialist reasoning (saving more lives) against principles that forbid using someone as a means.'),
  ('8d399448-3acd-538d-8687-ff57682ec60a', 'es',
   'El llamado "dilema del tranvía", en el que se decide desviar un vehículo para salvar a cinco personas sacrificando a una, se usa para discutir:',
   array['El conflicto entre calcular consecuencias y respetar deberes o derechos individuales', 'Las leyes físicas del movimiento', 'La historia del transporte público', 'El origen mítico del mundo'],
   'El dilema contrapone el razonamiento consecuencialista (salvar más vidas) a principios que prohíben usar a alguien como medio.'),
  ('5be1ac01-86fd-5673-874d-b79171e84376', 'en',
   'Utilitarianism, by Jeremy Bentham and John Stuart Mill, considers an action right when it:',
   array['Obeys religious tradition', 'Produces the greatest happiness for the greatest number of people', 'Is done only out of duty', 'Benefits only the person who performs it'],
   'Utilitarianism is consequentialist: it judges actions by their results in terms of general well-being.'),
  ('5be1ac01-86fd-5673-874d-b79171e84376', 'es',
   'El utilitarismo, de Jeremy Bentham y John Stuart Mill, considera correcta una acción cuando:',
   array['Obedece a la tradición religiosa', 'Produce la mayor felicidad para el mayor número de personas', 'Se hace solo por deber', 'Beneficia únicamente a quien la realiza'],
   'El utilitarismo es consecuencialista: juzga las acciones por sus resultados en términos de bienestar general.'),
  ('c885b972-ab34-5453-bbf6-68431f11a33f', 'en',
   'Kant''s ethics is called an ethics of duty (deontological) because:',
   array['It judges actions only by their results', 'It seeks pleasure as the ultimate goal', 'It follows the will of the majority', 'The moral worth of an action lies in its being done out of duty, according to reason'],
   'For Kant, a moral action is one done out of respect for the moral law, regardless of the consequences.'),
  ('c885b972-ab34-5453-bbf6-68431f11a33f', 'es',
   'La ética de Kant se llama ética del deber (deontológica) porque:',
   array['Evalúa las acciones solo por sus resultados', 'Busca el placer como fin último', 'Sigue la voluntad de la mayoría', 'El valor moral de la acción está en hacerse por deber, según la razón'],
   'Para Kant, la acción moral es la que se hace por respeto a la ley moral, independientemente de las consecuencias.'),
  ('2ec2f8cb-eb43-5a49-ae34-d9af2476b2fe', 'en',
   'Virtue ethics, of Aristotelian origin, mainly asks:',
   array['What kind of person should I be and what habits should I cultivate?', 'Which action produces the most pleasure?', 'Which universal rules must I follow without exception?', 'What does the State''s law allow?'],
   'Virtue ethics focuses on character: becoming just, brave and prudent through practice.'),
  ('2ec2f8cb-eb43-5a49-ae34-d9af2476b2fe', 'es',
   'La ética de las virtudes, de origen aristotélico, pregunta principalmente:',
   array['¿Qué tipo de persona debo ser y qué hábitos debo cultivar?', '¿Qué acción produce más placer?', '¿Qué reglas universales debo seguir sin excepción?', '¿Qué permite la ley del Estado?'],
   'La ética de las virtudes se centra en el carácter: volverse justo, valiente y prudente mediante la práctica.'),
  ('71640ef7-2ae5-5d0a-86ac-ce893be07ff9', 'en',
   'John Stuart Mill refined Bentham''s utilitarianism by stating that:',
   array['All pleasures have exactly the same value', 'Only duty matters, not consequences', 'There are higher (intellectual) and lower pleasures, which differ in quality', 'Happiness has no moral importance'],
   'Mill says it is better to be a dissatisfied human than a satisfied pig: the quality of pleasures counts.'),
  ('71640ef7-2ae5-5d0a-86ac-ce893be07ff9', 'es',
   'John Stuart Mill perfeccionó el utilitarismo de Bentham al afirmar que:',
   array['Todos los placeres tienen exactamente el mismo valor', 'Solo importa el deber, no las consecuencias', 'Hay placeres superiores (intelectuales) e inferiores, que difieren en calidad', 'La felicidad no tiene importancia moral'],
   'Mill dice que es mejor ser un humano insatisfecho que un cerdo satisfecho: la calidad de los placeres cuenta.'),
  ('c26fc5dd-3fef-574e-bd36-657e76b57e37', 'en',
   'A frequent criticism of utilitarianism is that it may:',
   array['Completely ignore people''s well-being', 'Justify sacrificing a minority''s rights for the sake of the majority''s well-being', 'Require following religious tradition', 'Forbid any calculation of consequences'],
   'If only the balance of happiness matters, unjust acts against a few could be approved; hence the defense of individual rights.'),
  ('c26fc5dd-3fef-574e-bd36-657e76b57e37', 'es',
   'Una crítica frecuente al utilitarismo es que puede:',
   array['Ignorar por completo el bienestar de las personas', 'Justificar sacrificar los derechos de una minoría en nombre del bienestar de la mayoría', 'Exigir que se siga la tradición religiosa', 'Prohibir cualquier cálculo de consecuencias'],
   'Si solo importa el saldo de felicidad, acciones injustas contra unos pocos podrían aprobarse; de ahí la defensa de los derechos individuales.'),
  ('57d1b7a7-707d-5381-ace2-9cbff8b7e029', 'en',
   'According to Kant, lying to save a friend from a murderer would be:',
   array['Right, because the consequence is good', 'Right, if the majority agrees', 'Morally indifferent', 'Wrong, because the prohibition on lying admits no exceptions based on consequences'],
   'In his dispute with Benjamin Constant, Kant holds that the duty of truthfulness applies unconditionally.'),
  ('57d1b7a7-707d-5381-ace2-9cbff8b7e029', 'es',
   'Según Kant, mentir para salvar a un amigo de un asesino sería:',
   array['Correcto, pues la consecuencia es buena', 'Correcto, si la mayoría está de acuerdo', 'Indiferente desde el punto de vista moral', 'Incorrecto, pues la prohibición de mentir no admite excepciones basadas en las consecuencias'],
   'En la polémica con Benjamin Constant, Kant sostiene que el deber de veracidad vale incondicionalmente.'),
  ('22fe91d7-908f-5f51-90f1-59772785860e', 'en',
   'Niccolò Machiavelli''s best-known work, about how to gain and keep power, is:',
   array['The Prince', 'The Republic', 'Leviathan', 'The Social Contract'],
   'In The Prince (1513), Machiavelli analyzes politics as it is, not as it ought to be.'),
  ('22fe91d7-908f-5f51-90f1-59772785860e', 'es',
   'La obra más conocida de Nicolás Maquiavelo, que trata de cómo conquistar y mantener el poder, es:',
   array['El Príncipe', 'La República', 'Leviatán', 'El Contrato Social'],
   'En El Príncipe (1513), Maquiavelo analiza la política tal como es, y no como debería ser.'),
  ('6f37139c-0c65-5bf8-b6cb-d96da282358e', 'en',
   'For Machiavelli, the ruler needs virtù, which means:',
   array['Religious purity', 'Inherited wealth', 'The ability to act skillfully in the face of circumstances', 'Obedience to the pope'],
   'Virtù is the prince''s ability to seize the moment and face fortuna (chance).'),
  ('6f37139c-0c65-5bf8-b6cb-d96da282358e', 'es',
   'Para Maquiavelo, el gobernante necesita virtù, que significa:',
   array['Pureza religiosa', 'Riqueza heredada', 'Capacidad de actuar con habilidad ante las circunstancias', 'Obediencia al papa'],
   'La virtù es la capacidad del príncipe de aprovechar la ocasión y enfrentar la fortuna (el azar).'),
  ('b8ab2e8e-662c-563b-b93e-24eb8ef1eecd', 'en',
   'Machiavelli is considered a founder of modern political science because:',
   array['He argued that politics must follow Christian morality', 'He separated political analysis from morality and religion, observing reality', 'He created the system of three powers', 'He proposed the end of all governments'],
   'He describes how power really works, independently of traditional morality.'),
  ('b8ab2e8e-662c-563b-b93e-24eb8ef1eecd', 'es',
   'Maquiavelo es considerado un fundador de la ciencia política moderna porque:',
   array['Defendió que la política debe seguir la moral cristiana', 'Separó el análisis político de la moral y la religión, observando la realidad', 'Creó el sistema de los tres poderes', 'Propuso el fin de todos los gobiernos'],
   'Describe el funcionamiento real del poder, con autonomía respecto de la moral tradicional.'),
  ('e82c24e5-14bb-516b-93d4-0318cfa085ab', 'en',
   'On the question "is it better to be loved or feared?", Machiavelli answers that the prince:',
   array['Should only be loved', 'Should be hated in order to command respect', 'Need not worry about it', 'Ideally would be both, but if he must choose, it is safer to be feared, without being hated'],
   'Love depends on the subjects'' will; fear, on the prince. But he must avoid hatred.'),
  ('e82c24e5-14bb-516b-93d4-0318cfa085ab', 'es',
   'Ante la pregunta "¿es mejor ser amado o temido?", Maquiavelo responde que el príncipe:',
   array['Debe ser solo amado', 'Debe ser odiado para imponer respeto', 'No necesita preocuparse por ello', 'Lo ideal sería ser ambas cosas, pero, si debe elegir, es más seguro ser temido, sin ser odiado'],
   'El amor depende de la voluntad de los súbditos; el temor, del príncipe. Pero debe evitar el odio.'),
  ('17b3b10f-b001-5b58-8cc0-535c85cba28f', 'en',
   'The concepts of virtù and fortuna, in Machiavelli, indicate that:',
   array['Everything in politics depends on fate, and nothing can be done', 'Rulers are chosen by God', 'Political success depends on the ruler''s ability to face chance', 'History is governed only by economic laws'],
   'Fortuna governs part of things, but virtù can resist and master circumstances.'),
  ('17b3b10f-b001-5b58-8cc0-535c85cba28f', 'es',
   'Los conceptos de virtù y fortuna, en Maquiavelo, indican que:',
   array['Todo en la política depende del destino, y nada puede hacerse', 'Los gobernantes son elegidos por Dios', 'El éxito político depende de la capacidad del gobernante de enfrentar el azar', 'La historia se rige solo por leyes económicas'],
   'La fortuna gobierna parte de las cosas, pero la virtù puede resistir y dominar las circunstancias.'),
  ('9a1c479c-d447-5073-8201-20e479b75189', 'en',
   'The expression "the end justifies the means", popularly attributed to Machiavelli, is considered a simplification because:',
   array['He judges actions by the goal of preserving the State, and does not authorize any action for any end', 'He never wrote about politics', 'He argued that Christian morality must always prevail', 'He opposed any strong government'],
   'The phrase does not appear literally in his work; Machiavelli judges the prince''s actions by the preservation of the State.'),
  ('9a1c479c-d447-5073-8201-20e479b75189', 'es',
   'La expresión "el fin justifica los medios", atribuida popularmente a Maquiavelo, se considera una simplificación porque:',
   array['Él analiza las acciones por el objetivo de mantener el Estado, y no autoriza cualquier acción para cualquier fin', 'Nunca trató de política', 'Defendía que la moral cristiana siempre debe prevalecer', 'Estaba en contra de cualquier gobierno fuerte'],
   'La frase no aparece literalmente en su obra; Maquiavelo evalúa las acciones del príncipe por la conservación del Estado.'),
  ('0e884ebc-a856-5511-9f00-deb253875cf4', 'en',
   'For Thomas Hobbes, in the state of nature, without government, human life would be:',
   array['Peaceful and harmonious', 'A war of all against all', 'Organized by the Church', 'Ruled by private property'],
   'Hobbes describes life without the State as "solitary, poor, nasty, brutish and short": man is a wolf to man.'),
  ('0e884ebc-a856-5511-9f00-deb253875cf4', 'es',
   'Para Thomas Hobbes, en el estado de naturaleza, sin gobierno, la vida humana sería:',
   array['Pacífica y armoniosa', 'Una guerra de todos contra todos', 'Organizada por la Iglesia', 'Regida por la propiedad privada'],
   'Hobbes describe la vida sin Estado como "solitaria, pobre, desagradable, brutal y corta": el hombre es un lobo para el hombre.'),
  ('4e032cfc-14a4-5262-a61b-fe778b8b784c', 'en',
   'The phrase "man is born good, society corrupts him" is associated with:',
   array['Thomas Hobbes', 'John Locke', 'Niccolò Machiavelli', 'Jean-Jacques Rousseau'],
   'Rousseau saw human beings as naturally good; property and social inequality corrupt them.'),
  ('4e032cfc-14a4-5262-a61b-fe778b8b784c', 'es',
   'La frase "el hombre nace bueno, la sociedad lo corrompe" se asocia a:',
   array['Thomas Hobbes', 'John Locke', 'Nicolás Maquiavelo', 'Jean-Jacques Rousseau'],
   'Rousseau veía al ser humano naturalmente bueno; la propiedad y la desigualdad social lo corrompen.'),
  ('71891489-fa57-533f-be2e-941bc104f544', 'en',
   'For John Locke, the natural rights that government must protect are:',
   array['Life, liberty and property', 'Obedience, faith and work', 'Power, glory and wealth', 'Absolute equality of goods'],
   'Locke laid the foundations of liberalism: the State exists to protect these rights, and the people may resist a tyrannical government.'),
  ('71891489-fa57-533f-be2e-941bc104f544', 'es',
   'Para John Locke, los derechos naturales que el gobierno debe proteger son:',
   array['Vida, libertad y propiedad', 'Obediencia, fe y trabajo', 'Poder, gloria y riqueza', 'Igualdad absoluta de bienes'],
   'Locke fundamenta el liberalismo: el Estado existe para proteger esos derechos, y el pueblo puede resistirse al gobierno tiránico.'),
  ('f26c749a-bf3d-5bda-a87e-932101140e88', 'en',
   'In Rousseau, the "general will" is:',
   array['The sum of each person''s private interests', 'The will of the absolute king', 'The will directed at the common good, which expresses popular sovereignty', 'The opinion of the richest'],
   'The general will aims at the common interest and is the basis of popular sovereignty, which cannot be alienated.'),
  ('f26c749a-bf3d-5bda-a87e-932101140e88', 'es',
   'En Rousseau, la "voluntad general" es:',
   array['La suma de los intereses particulares de cada uno', 'La voluntad del rey absoluto', 'La voluntad orientada al bien común, que expresa la soberanía del pueblo', 'La opinión de los más ricos'],
   'La voluntad general busca el interés común y es la base de la soberanía popular, que no puede enajenarse.'),
  ('7f8ce014-2db2-5060-bab0-82de54395b19', 'en',
   'In Leviathan, Hobbes justifies a strong sovereign power because:',
   array['The king is chosen directly by God', 'Property is an absolute right prior to the State', 'The people must take part directly in every decision', 'Only a power able to inspire fear guarantees the peace and security individuals seek when making the contract'],
   'Individuals transfer their rights to the sovereign in exchange for security; without it, they would return to the war of all against all.'),
  ('7f8ce014-2db2-5060-bab0-82de54395b19', 'es',
   'En Leviatán, Hobbes justifica un poder soberano fuerte porque:',
   array['El rey es elegido directamente por Dios', 'La propiedad es un derecho absoluto anterior al Estado', 'El pueblo debe participar directamente en todas las decisiones', 'Solo un poder capaz de infundir temor garantiza la paz y la seguridad que los individuos buscan al hacer el contrato'],
   'Los individuos transfieren sus derechos al soberano a cambio de seguridad; sin él, volverían a la guerra de todos contra todos.'),
  ('3cbebab8-ab74-5ad6-96bf-7246aadf13a8', 'en',
   'What Hobbes, Locke and Rousseau have in common is the idea that:',
   array['Kings'' power has a divine origin', 'The legitimacy of the State rests on an agreement (contract) between individuals', 'The state of nature is identical for all three', 'Property must be abolished'],
   'All three are social contract theorists, although they disagree about the state of nature and the kind of legitimate government.'),
  ('3cbebab8-ab74-5ad6-96bf-7246aadf13a8', 'es',
   'Lo que Hobbes, Locke y Rousseau tienen en común es la idea de que:',
   array['El poder de los reyes tiene origen divino', 'La legitimidad del Estado se funda en un acuerdo (contrato) entre los individuos', 'El estado de naturaleza es idéntico para los tres', 'La propiedad debe abolirse'],
   'Los tres son contractualistas, aunque discrepan sobre el estado de naturaleza y el tipo de gobierno legítimo.'),
  ('414112ff-3211-5a99-ba61-d6c7e437ee1a', 'en',
   'The phrase "God is dead" is associated with:',
   array['Friedrich Nietzsche', 'Karl Marx', 'René Descartes', 'Saint Augustine'],
   'Nietzsche uses the expression to indicate the exhaustion of the traditional values of Western culture.'),
  ('414112ff-3211-5a99-ba61-d6c7e437ee1a', 'es',
   'La frase "Dios ha muerto" se asocia a:',
   array['Friedrich Nietzsche', 'Karl Marx', 'René Descartes', 'San Agustín'],
   'Nietzsche usa la expresión para indicar el agotamiento de los valores tradicionales de la cultura occidental.'),
  ('89b610a8-a506-5012-8999-f01c90512bf2', 'en',
   'Nietzsche proposed the "revaluation of all values", which means:',
   array['Uncritically accepting traditional morality', 'Turning all values into money', 'Criticizing traditional values and creating new ones that affirm life', 'Returning to the values of the Middle Ages'],
   'Nietzsche criticizes the morality that denies life and proposes values that affirm will and existence.'),
  ('89b610a8-a506-5012-8999-f01c90512bf2', 'es',
   'Nietzsche propuso la "transvaloración de todos los valores", que significa:',
   array['Aceptar sin críticas la moral tradicional', 'Convertir todos los valores en dinero', 'Criticar los valores tradicionales y crear otros nuevos, afirmativos de la vida', 'Volver a los valores de la Edad Media'],
   'Nietzsche critica la moral que niega la vida y propone valores que afirmen la voluntad y la existencia.'),
  ('80f3cd23-f668-5b39-ae03-e6fd2f684ae1', 'en',
   'In Nietzsche, "slave morality" is one that:',
   array['Arises from strength and the affirmation of life', 'Arises from the resentment of the weak, who invert the values of the strong', 'Was created by the heroic ancient Greeks', 'Values pride and nobility'],
   'In the Genealogy of Morals, slave morality turns weakness into virtue and condemns what is strong.'),
  ('80f3cd23-f668-5b39-ae03-e6fd2f684ae1', 'es',
   'En Nietzsche, la "moral de esclavos" es aquella que:',
   array['Nace de la fuerza y de la afirmación de la vida', 'Nace del resentimiento de los débiles, que invierten los valores de los fuertes', 'Fue creada por los antiguos griegos heroicos', 'Valora el orgullo y la nobleza'],
   'En la Genealogía de la moral, la moral de esclavos convierte la debilidad en virtud y condena lo fuerte.'),
  ('c65b167d-7e6c-577d-ac2f-9f2144d51f1f', 'en',
   'Nietzsche''s concept of the overman (Übermensch) refers to someone who:',
   array['Has supernatural powers', 'Strictly obeys religious laws', 'Seeks absolute equality among all', 'Overcomes inherited values and creates their own'],
   'The Übermensch is a goal: the human being who overcomes themselves and affirms life by creating their own values.'),
  ('c65b167d-7e6c-577d-ac2f-9f2144d51f1f', 'es',
   'El concepto nietzscheano de superhombre (Übermensch) se refiere a alguien que:',
   array['Tiene poderes sobrenaturales', 'Obedece rigurosamente las leyes religiosas', 'Busca la igualdad absoluta entre todos', 'Supera los valores heredados y crea sus propios valores'],
   'El Übermensch es una meta: el ser humano que se supera y afirma la vida creando valores propios.'),
  ('b81ff383-8f2f-566e-8215-30bfcb4cedb2', 'en',
   'In The Birth of Tragedy, Nietzsche contrasts two drives of Greek culture:',
   array['The rational and the empirical', 'The political and the religious', 'The Apollonian (form, measure) and the Dionysian (intoxication, excess)', 'The material and the spiritual'],
   'Greek tragedy would be born of the union between the Apollonian, of order and form, and the Dionysian, of vital force and chaos.'),
  ('b81ff383-8f2f-566e-8215-30bfcb4cedb2', 'es',
   'En El nacimiento de la tragedia, Nietzsche contrapone dos impulsos de la cultura griega:',
   array['Lo racional y lo empírico', 'Lo político y lo religioso', 'Lo apolíneo (forma, medida) y lo dionisíaco (embriaguez, exceso)', 'Lo material y lo espiritual'],
   'La tragedia griega nacería de la unión entre lo apolíneo, del orden y la forma, y lo dionisíaco, de la fuerza vital y el caos.'),
  ('336986fe-0150-5c54-a6dc-c750576a6dbe', 'en',
   'The idea of eternal recurrence, in Nietzsche, works as a test that asks:',
   array['Would you want to live your life exactly the same, infinitely many times?', 'What is the principle of all things?', 'How can God''s existence be proved?', 'What is the best form of government?'],
   'Whoever can will the eternal recurrence of their life affirms it fully, without resentment.'),
  ('336986fe-0150-5c54-a6dc-c750576a6dbe', 'es',
   'La idea del eterno retorno, en Nietzsche, funciona como una prueba que pregunta:',
   array['¿Querrías vivir tu vida exactamente igual, infinitas veces?', '¿Cuál es el principio de todas las cosas?', '¿Cómo probar la existencia de Dios?', '¿Cuál es la mejor forma de gobierno?'],
   'Quien puede querer el eterno retorno de su vida la afirma plenamente, sin resentimiento.'),
  ('60bbe3b3-b865-50c4-8cd5-bbe25de697d8', 'en',
   'For Jean-Paul Sartre, "existence precedes essence", which means that:',
   array['We are born with a fixed nature defined by God', 'Human beings first exist and then define themselves through their choices', 'Human essence is determined by biology', 'Nothing we do matters'],
   'There is no prior human nature: we are what we make of ourselves.'),
  ('60bbe3b3-b865-50c4-8cd5-bbe25de697d8', 'es',
   'Para Jean-Paul Sartre, "la existencia precede a la esencia", lo que significa que:',
   array['Nacemos con una naturaleza fija definida por Dios', 'El ser humano primero existe y luego se define por sus elecciones', 'La esencia humana está determinada por la biología', 'Nada de lo que hacemos importa'],
   'No hay una naturaleza humana previa: somos lo que hacemos de nosotros mismos.'),
  ('a451d51d-52d2-54da-b625-6e72ff0495c4', 'en',
   'The phrase "man is condemned to be free" is by:',
   array['Nietzsche', 'Kant', 'Marx', 'Sartre'],
   'For Sartre, we cannot escape freedom: even not choosing is a choice.'),
  ('a451d51d-52d2-54da-b625-6e72ff0495c4', 'es',
   'La frase "el hombre está condenado a ser libre" es de:',
   array['Nietzsche', 'Kant', 'Marx', 'Sartre'],
   'Para Sartre, no podemos escapar de la libertad: incluso no elegir es una elección.'),
  ('1e9345bb-73c8-5e5e-afd2-3032581d33df', 'en',
   'The phrase "one is not born, but rather becomes, a woman", by Simone de Beauvoir, states that:',
   array['Being a woman is a social and historical construction, not a biological destiny', 'Women should withdraw from public life', 'Nature defines all social roles', 'Men and women have no biological differences at all'],
   'In The Second Sex, Beauvoir shows how female roles are built by society.'),
  ('1e9345bb-73c8-5e5e-afd2-3032581d33df', 'es',
   'La frase "no se nace mujer, se llega a serlo", de Simone de Beauvoir, afirma que:',
   array['Ser mujer es una construcción social e histórica, y no un destino biológico', 'Las mujeres deben apartarse de la vida pública', 'La naturaleza define todos los papeles sociales', 'Hombres y mujeres no tienen ninguna diferencia biológica'],
   'En El segundo sexo, Beauvoir muestra cómo los papeles femeninos son construidos por la sociedad.'),
  ('0537f264-f8dc-515a-bdf4-b81afa32d64c', 'en',
   'For Sartre, "bad faith" occurs when a person:',
   array['Lies to others for their own interest', 'Practices a religion', 'Denies their own freedom, pretending they had no choice', 'Doubts everything methodically'],
   'In bad faith, a person hides from the anguish of freedom by attributing their actions to fate, nature or others.'),
  ('0537f264-f8dc-515a-bdf4-b81afa32d64c', 'es',
   'Para Sartre, la "mala fe" ocurre cuando la persona:',
   array['Miente a los demás por interés', 'Practica una religión', 'Niega su propia libertad, fingiendo que no tenía elección', 'Duda de todo metódicamente'],
   'En la mala fe, la persona se esconde de la angustia de la libertad atribuyendo sus actos al destino, a la naturaleza o a los demás.'),
  ('037980cd-437a-5b3e-9500-aa53cdef4f11', 'en',
   'For Albert Camus, in The Myth of Sisyphus, the absurd arises:',
   array['From the certainty that life has a meaning given by God', 'From the clash between the human search for meaning and the silence of the world', 'From the victory of reason over emotions', 'From the political organization of society'],
   'Camus concludes that "one must imagine Sisyphus happy": lucid revolt in the face of the absurd gives life value.'),
  ('037980cd-437a-5b3e-9500-aa53cdef4f11', 'es',
   'Para Albert Camus, en El mito de Sísifo, el absurdo surge:',
   array['De la certeza de que la vida tiene un sentido dado por Dios', 'Del choque entre la búsqueda humana de sentido y el silencio del mundo', 'De la victoria de la razón sobre las emociones', 'De la organización política de la sociedad'],
   'Camus concluye que "hay que imaginar a Sísifo feliz": la rebelión lúcida ante el absurdo da valor a la vida.'),
  ('c601a511-b8f4-5ba5-af47-0cde8b5cb299', 'en',
   'For the existentialists, anguish is:',
   array['An illness to be cured with medicine', 'A feeling exclusive to those without religion', 'The result of lack of wealth', 'The experience of realizing oneself free and responsible for one''s choices, with no guarantees'],
   'Anguish reveals freedom: by choosing, we answer for ourselves and, in a way, for humanity.'),
  ('c601a511-b8f4-5ba5-af47-0cde8b5cb299', 'es',
   'Para los existencialistas, la angustia es:',
   array['Una enfermedad que debe curarse con medicamentos', 'Un sentimiento exclusivo de quien no tiene religión', 'Resultado de la falta de riqueza', 'La experiencia de percibirse libre y responsable de las propias elecciones, sin garantías'],
   'La angustia revela la libertad: al elegir, respondemos por nosotros y, en cierto modo, por la humanidad.'),
  ('1ae5ffaf-aaf8-5f01-917a-da3d2cc36c73', 'en',
   'The Frankfurt School became known for developing:',
   array['Formal logic', 'Scholastic philosophy', 'Critical theory of society', 'Quantum physics'],
   'Critical theory, by authors such as Adorno, Horkheimer, Marcuse and Habermas, critically analyzes modern society.'),
  ('1ae5ffaf-aaf8-5f01-917a-da3d2cc36c73', 'es',
   'La Escuela de Fráncfort se hizo conocida por desarrollar la:',
   array['Lógica formal', 'Filosofía escolástica', 'Teoría crítica de la sociedad', 'Física cuántica'],
   'La teoría crítica, de autores como Adorno, Horkheimer, Marcuse y Habermas, analiza críticamente la sociedad moderna.'),
  ('d11c5e79-838b-5f1b-947d-fe2dfe9b480f', 'en',
   'Adorno and Horkheimer created the concept of the "culture industry" to criticize:',
   array['The mass production of culture as a standardized commodity', 'The traditional arts of Indigenous peoples', 'Free public education', 'Industrial agriculture'],
   'The culture industry turns culture into a standardized consumer product that encourages conformity.'),
  ('d11c5e79-838b-5f1b-947d-fe2dfe9b480f', 'es',
   'Adorno y Horkheimer crearon el concepto de "industria cultural" para criticar:',
   array['La producción en masa de cultura como mercancía estandarizada', 'Las artes tradicionales de los pueblos indígenas', 'La educación pública gratuita', 'La agricultura industrial'],
   'La industria cultural convierte la cultura en un producto de consumo estandarizado que favorece el conformismo.'),
  ('cd837e04-4c5f-56ef-b899-fd06e88ee2e2', 'en',
   '"Instrumental reason", criticized by the Frankfurt School, is the reason that:',
   array['Reflects on the ultimate ends of human life', 'Seeks only disinterested truth', 'Opposes all technology', 'Cares only about the most efficient means, without questioning the ends'],
   'In the Dialectic of Enlightenment, reason reduced to calculation and efficiency can serve domination.'),
  ('cd837e04-4c5f-56ef-b899-fd06e88ee2e2', 'es',
   'La "razón instrumental", criticada por la Escuela de Fráncfort, es la razón que:',
   array['Reflexiona sobre los fines últimos de la vida humana', 'Busca solo la verdad desinteresada', 'Se opone a cualquier técnica', 'Se preocupa solo por los medios más eficientes, sin cuestionar los fines'],
   'En la Dialéctica de la Ilustración, la razón reducida a cálculo y eficiencia puede servir a la dominación.'),
  ('131154a6-c5c5-50bf-8643-76ea185969be', 'en',
   'Jürgen Habermas proposed communicative action, based on:',
   array['Force and coercion', 'Rational dialogue aimed at mutual understanding among participants', 'Obedience to charismatic leaders', 'Individual calculation of advantages'],
   'For Habermas, legitimate norms arise from free debate in which the best arguments prevail.'),
  ('131154a6-c5c5-50bf-8643-76ea185969be', 'es',
   'Jürgen Habermas propuso la acción comunicativa, basada:',
   array['En la fuerza y la coerción', 'En el diálogo racional en busca de entendimiento entre los participantes', 'En la obediencia a líderes carismáticos', 'En el cálculo individual de ventajas'],
   'Para Habermas, las normas legítimas surgen del debate libre en el que valen los mejores argumentos.'),
  ('7c36a691-3acd-5f3b-965c-ef00c5c13e9c', 'en',
   'Walter Benjamin, in "The Work of Art in the Age of Mechanical Reproduction", states that mass reproduction:',
   array['Increases the unique aura of the original work', 'Prevents any public access to art', 'Makes the work lose its "aura", but widens access and changes its social function', 'Changes nothing in our relationship with art'],
   'Photography and cinema remove the work''s uniqueness (aura), but democratize access and politicize art.'),
  ('7c36a691-3acd-5f3b-965c-ef00c5c13e9c', 'es',
   'Walter Benjamin, en "La obra de arte en la época de su reproductibilidad técnica", afirma que la reproducción en masa:',
   array['Aumenta el aura única de la obra original', 'Impide cualquier acceso del público al arte', 'Hace que la obra pierda su "aura", pero amplía el acceso y cambia su función social', 'No altera en nada la relación con el arte'],
   'La fotografía y el cine quitan la unicidad (aura) a la obra, pero democratizan el acceso y politizan el arte.'),
  ('0f931db6-d9bf-5b0b-97c8-8ab956cd0994', 'en',
   'Herbert Marcuse, in One-Dimensional Man, criticizes advanced industrial society because it:',
   array['Integrates individuals into consumption and reduces their ability to imagine critical alternatives', 'Completely prevents consumption', 'Returns to the feudal way of life', 'Eliminates all forms of technology'],
   'Abundance and consumption would create false needs that neutralize criticism and opposition.'),
  ('0f931db6-d9bf-5b0b-97c8-8ab956cd0994', 'es',
   'Herbert Marcuse, en El hombre unidimensional, critica la sociedad industrial avanzada porque:',
   array['Integra a los individuos al consumo y reduce su capacidad de pensar alternativas críticas', 'Impide totalmente el consumo', 'Vuelve al modo de vida feudal', 'Elimina toda forma de tecnología'],
   'La abundancia y el consumo crearían falsas necesidades que neutralizan la crítica y la oposición.'),
  ('6940e7c6-c453-58a4-a3b6-93013cfc90e9', 'en',
   'An argument is made up of:',
   array['Just a personal opinion', 'Premises and a conclusion supported by them', 'Unanswered questions', 'A list of definitions'],
   'In an argument, the premises offer reasons to accept the conclusion.'),
  ('6940e7c6-c453-58a4-a3b6-93013cfc90e9', 'es',
   'Un argumento está formado por:',
   array['Solo una opinión personal', 'Premisas y una conclusión que se apoya en ellas', 'Preguntas sin respuesta', 'Una lista de definiciones'],
   'En un argumento, las premisas ofrecen razones para aceptar la conclusión.'),
  ('98b61246-e156-5557-9095-28e377f26d0d', 'en',
   '"All men are mortal. Socrates is a man. Therefore, Socrates is mortal." This argument is an example of:',
   array['Induction', 'Fallacy', 'Analogy', 'Deductive syllogism'],
   'In Aristotle''s syllogism, the conclusion follows necessarily from the two premises.'),
  ('98b61246-e156-5557-9095-28e377f26d0d', 'es',
   '"Todo hombre es mortal. Sócrates es hombre. Luego, Sócrates es mortal." Este argumento es un ejemplo de:',
   array['Inducción', 'Falacia', 'Analogía', 'Silogismo deductivo'],
   'En el silogismo de Aristóteles, la conclusión se sigue necesariamente de las dos premisas.'),
  ('d057f4b5-5621-5df6-90ca-cb34ed028aa7', 'en',
   'Attacking the person who presents an argument, instead of discussing the argument itself, is the fallacy called:',
   array['Ad hominem', 'Appeal to authority', 'False cause', 'Straw man'],
   'In the ad hominem fallacy, the author is discredited to reject their idea without examining it.'),
  ('d057f4b5-5621-5df6-90ca-cb34ed028aa7', 'es',
   'Atacar a la persona que presenta un argumento, en lugar de discutir el argumento en sí, es la falacia llamada:',
   array['Ad hominem', 'Apelación a la autoridad', 'Falsa causa', 'Hombre de paja'],
   'En la falacia ad hominem, se descalifica al autor para rechazar su idea sin examinarla.'),
  ('20102b0c-85ec-5632-8cb7-2c313201393a', 'en',
   'An inductive argument is characterized by:',
   array['Having a necessarily true conclusion if the premises are true', 'Having no premises', 'Moving from particular cases to a probable general conclusion', 'Always being a fallacy'],
   'Induction generalizes from observations; its conclusion is probable, not necessary.'),
  ('20102b0c-85ec-5632-8cb7-2c313201393a', 'es',
   'Un argumento inductivo se caracteriza por:',
   array['Tener una conclusión necesariamente verdadera si las premisas son verdaderas', 'No tener premisas', 'Partir de casos particulares hacia una conclusión general probable', 'Ser siempre una falacia'],
   'La inducción generaliza a partir de observaciones; su conclusión es probable, no necesaria.'),
  ('8e2b6a16-1232-5800-8215-a204384b64ce', 'en',
   'In logic, an argument is valid when:',
   array['All its premises are true', 'It is impossible for the premises to be true and the conclusion false', 'Most people agree with it', 'The conclusion is true, whatever the reasoning'],
   'Validity concerns form: if the premises are true, the conclusion must be true. A valid argument may have false premises.'),
  ('8e2b6a16-1232-5800-8215-a204384b64ce', 'es',
   'En lógica, un argumento es válido cuando:',
   array['Todas sus premisas son verdaderas', 'Es imposible que las premisas sean verdaderas y la conclusión falsa', 'La mayoría de las personas está de acuerdo con él', 'La conclusión es verdadera, sea cual sea el razonamiento'],
   'La validez se refiere a la forma: si las premisas son verdaderas, la conclusión necesariamente lo será. Un argumento válido puede tener premisas falsas.'),
  ('dfe37131-95bd-530c-a503-5eb24928a087', 'en',
   'Distorting the opponent''s position, making it weaker, in order to refute it easily is the fallacy of the:',
   array['Appeal to emotion', 'Ad hominem', 'False dilemma', 'Straw man'],
   'In the straw man fallacy, a caricature of the argument is refuted, not the real argument.'),
  ('dfe37131-95bd-530c-a503-5eb24928a087', 'es',
   'Distorsionar la posición del oponente, haciéndola más débil, para luego refutarla fácilmente es la falacia del:',
   array['Apelación a la emoción', 'Ad hominem', 'Falso dilema', 'Hombre de paja'],
   'En la falacia del hombre de paja, se refuta una versión caricaturizada del argumento, no el argumento real.'),
  ('be3c35be-f27d-5579-82a1-234041569d81', 'en',
   'The classical definition of knowledge, discussed since Plato, is:',
   array['Any opinion someone holds', 'What the majority believes', 'Justified true belief', 'Everything written in books'],
   'For there to be knowledge, believing is not enough: the belief must be true and well justified.'),
  ('be3c35be-f27d-5579-82a1-234041569d81', 'es',
   'La definición clásica de conocimiento, discutida desde Platón, es:',
   array['Cualquier opinión que alguien tenga', 'Lo que cree la mayoría', 'Creencia verdadera y justificada', 'Todo lo que está escrito en los libros'],
   'Para que haya conocimiento no basta creer: la creencia debe ser verdadera y estar bien justificada.'),
  ('5a07fd65-1073-5ef7-bfc8-184f84ec53d8', 'en',
   'Skepticism, in the theory of knowledge, is the position that:',
   array['Doubts whether we can reach certain knowledge', 'Claims that everything can be known with certainty', 'Holds that only religion provides knowledge', 'Considers sense experience infallible'],
   'The skeptic questions whether certainty is possible; some suspend judgment, others doubt specific areas.'),
  ('5a07fd65-1073-5ef7-bfc8-184f84ec53d8', 'es',
   'El escepticismo, en la teoría del conocimiento, es la posición que:',
   array['Duda de la posibilidad de alcanzar un conocimiento cierto', 'Afirma que todo puede conocerse con certeza', 'Defiende que solo la religión da conocimiento', 'Considera infalible la experiencia sensible'],
   'El escéptico cuestiona si es posible la certeza; algunos suspenden el juicio, otros dudan de áreas específicas.'),
  ('00a79b7b-c19f-5b76-ac7f-c0d6e58fc776', 'en',
   'For Karl Popper, a theory is scientific when:',
   array['It can be proved definitively true', 'It is accepted by most scientists', 'It was formulated by a famous scientist', 'It is falsifiable, that is, testable and potentially refutable by experience'],
   'The criterion of falsifiability distinguishes science from non-science: scientific theories run the risk of being refuted.'),
  ('00a79b7b-c19f-5b76-ac7f-c0d6e58fc776', 'es',
   'Para Karl Popper, una teoría es científica cuando:',
   array['Puede probarse definitivamente verdadera', 'Es aceptada por la mayoría de los científicos', 'Fue formulada por un científico famoso', 'Puede ser falsada, es decir, puesta a prueba y potencialmente refutada por la experiencia'],
   'El criterio de falsabilidad distingue la ciencia de la no ciencia: las teorías científicas corren el riesgo de ser refutadas.'),
  ('c995fd0b-2309-59b9-a78d-5202bb302faf', 'en',
   'Thomas Kuhn called a "scientific revolution" the moment when:',
   array['Science stops progressing', 'One paradigm is replaced by another, as in the shift from geocentrism to heliocentrism', 'Scientists refuse to do experiments', 'Religion takes control of science'],
   'For Kuhn, normal science works within a paradigm; accumulated anomalies lead to a paradigm shift.'),
  ('c995fd0b-2309-59b9-a78d-5202bb302faf', 'es',
   'Thomas Kuhn llamó "revolución científica" al momento en que:',
   array['La ciencia deja de progresar', 'Un paradigma es sustituido por otro, como en el paso del geocentrismo al heliocentrismo', 'Los científicos se niegan a hacer experimentos', 'La religión pasa a controlar la ciencia'],
   'Para Kuhn, la ciencia normal opera dentro de un paradigma; las anomalías acumuladas llevan a un cambio de paradigma.'),
  ('5f9fa0ec-365f-584e-a165-57f1c405b0a0', 'en',
   'The so-called "Gettier problem" showed that defining knowledge as justified true belief:',
   array['Can fail, since there are cases of justified true belief that do not seem to be knowledge', 'Is perfect and admits no criticism', 'Was created by Descartes', 'Applies only to mathematics'],
   'Gettier presented cases in which someone is right by luck, with good justification, without really knowing.'),
  ('5f9fa0ec-365f-584e-a165-57f1c405b0a0', 'es',
   'El llamado "problema de Gettier" mostró que la definición de conocimiento como creencia verdadera justificada:',
   array['Puede fallar, pues hay casos de creencia verdadera y justificada que no parecen ser conocimiento', 'Es perfecta y no admite críticas', 'Fue creada por Descartes', 'Solo vale para las matemáticas'],
   'Gettier presentó casos en los que alguien acierta por suerte, con buena justificación, sin saber realmente.'),
  ('6ef6217a-0c0e-5688-b204-9863a1660e1c', 'en',
   'Kant''s distinction between analytic and synthetic judgments states that an analytic judgment:',
   array['Expands our knowledge with data from experience', 'Always depends on empirical observation', 'Has the predicate contained in the concept of the subject, as in "every bachelor is unmarried"', 'Is always false'],
   'In an analytic judgment the predicate only makes the subject explicit; a synthetic one adds something new to the concept.'),
  ('6ef6217a-0c0e-5688-b204-9863a1660e1c', 'es',
   'La distinción de Kant entre juicios analíticos y sintéticos afirma que un juicio analítico:',
   array['Amplía nuestro conocimiento con datos de la experiencia', 'Depende siempre de la observación empírica', 'Tiene el predicado contenido en el concepto del sujeto, como en "todo soltero es no casado"', 'Es siempre falso'],
   'En el juicio analítico el predicado solo explicita al sujeto; el sintético añade algo nuevo al concepto.')
) as v(id, locale, prompt, options, explanation)
join questions q
  on q.id = v.id::uuid
 and cardinality(q.options) = cardinality(v.options)
on conflict (question_id, locale) do update
  set prompt = excluded.prompt,
      options = excluded.options,
      explanation = excluded.explanation;
